-- Dungeon and boss lore from Blizzard's Encounter Journal. GENERATED by tools/build_dungeon_lore.py: do not edit.
-- Source: wago.tools db2 JournalInstance / JournalEncounter / JournalEncounterSection (retail client tables).
local ADDON, ns = ...
local L = {}
ns.dungeonLore = L
L.dungeons, L.bosses = {}, {}
local d, b = L.dungeons, L.bosses
d[209] = {name="Shadowfang Keep", description="Looming over Pyrewood Village from the southern bluffs of Silverpine Forest, Shadowfang Keep casts a shadow as dark as its legacy. Sinister forces occupy these ruins, formerly the dwelling of the mad archmage Arugal's worgen. The restless shade of Baron Silverlaine lingers, while Lord Godfrey and his cabal of erstwhile Gilnean noblemen plot against their enemies both living and undead."}
d[491] = {name="Razorfen Kraul", description="Legends state that where the demigod Agamaggan fell, his blood gave rise to great masses of thorny vines. Many quilboar have taken up residence in the largest cluster of giant thorns, the Razorfen, which they revere as Agamaggan's resting place."}
d[717] = {name="The Stockade", description="Stormwind Stockade is a closely guarded prison built beneath the canals of Stormwind City. Warden Thelwater keeps watch over the stockade and the highly dangerous criminals who call it home. Recently, the inmates revolted, overthrowing their guards and plunging the prison into a state of pandemonium."}
d[718] = {name="Wailing Caverns", description="Years ago, the famed druid Naralex and his followers descended into the shadowy Wailing Caverns, named for the mournful cry one hears when steam bursts from the cave system's fissures. Naralex planned to use the underground springs to restore lushness to the arid Barrens. But upon entering the Emerald Dream, he saw his vision of regrowth turn into a waking nightmare, one that has plagued the caverns ever since."}
d[719] = {name="Blackfathom Deeps", description="Once dedicated to the night elves' goddess Elune, Blackfathom Deeps was thought to have been destroyed during the Sundering, lost beneath the ocean. Millennia later, members of the Twilight's Hammer cult were drawn to the temple by whispers and foul dreams. After sacrificing untold numbers of innocents, the cult was rewarded with a new task: to protect one of the Old Gods' most cherished creatures, a pet that is still in need of nurturing before he can unleash his dark powers on the world."}
d[721] = {name="Gnomeregan", description="Built deep within the mountains of Dun Morogh, the wondrous city of Gnomeregan was a testament to the gnomes' intelligence and industry. But when the capital was invaded by troggs, the gnomish high tinker was betrayed by his advisor Sicco Thermaplugg. As a result, Gnomeregan was irradiated, and most of its inhabitants slain. The surviving gnomes fled, vowing to return someday and retake their home."}
d[722] = {name="Razorfen Downs", description="Legends state that where the demigod Agamaggan fell, his blood gave rise to great masses of thorny vines. Recently, scouts have reported seeing undead milling about the region, engendering fears that the dreaded Scourge may be moving to conquer Kalimdor."}
d[796] = {name="Scarlet Monastery", description="The Crusade's fanatical leaders direct their followers from the Scarlet Cathedral, at the heart of the monastery grounds. This heavily guarded location functions as the order's headquarters, and some of the most zealous and intolerant crusaders roam the halls of this once-hallowed place."}
d[1176] = {name="Zul'Farrak", description="Zul'Farrak was once the shining jewel of Tanaris, ferociously protected by the cunning Sandfury tribe. Despite the trolls' tenacity, this isolated group was forced to surrender much of its territory throughout history. Now, it appears that Zul'Farrak's inhabitants are creating a horrific army of undead trolls to conquer the surrounding region. Other disturbing rumors tell of an ancient creature sleeping within the city--one, if awakened, will rain death and destruction across Tanaris."}
d[1337] = {name="Uldaman", description="Uldaman is an ancient titan vault buried deep within the earth. It is said the titans sealed away a failed experiment there and then moved on to a new project, related to the genesis of the dwarves. Tales of a fabled treasure containing great knowledge have enticed would-be treasure hunters to dig deeper into the secrets of Uldaman, a task made perilous by the presence of stone defenders, savage troggs, Dark Iron invaders, and other dangers lurking in the lost city."}
d[1477] = {name="The Temple of Atal'Hakkar", description="Thousands of years ago, the Gurubashi empire was plunged into a civil war by a powerful sect of priests, the Atal'ai, who sought to summon to Azeroth an avatar of their god of blood, Hakkar the Soulflayer. The Gurubashi people exiled the Atal'ai to the Swamp of Sorrows, where the priests built the Temple of Atal'Hakkar. Ysera, Aspect of the green dragonflight, sank the temple beneath the swamp and assigned wardens to ensure that the summoning rituals never be performed again."}
d[1581] = {name="The Deadmines", description="It is said the Deadmines' gold deposits once accounted for a third of Stormwind's treasure reserves. Amid the chaos of the First War, the mines were abandoned and later thought to be haunted, leaving them relatively untouched until the Defias Brotherhood--a group of former laborers turned brigands--claimed the labyrinth as a base of operations for its subversive activities against Stormwind."}
d[1583] = {name="Blackrock Spire", description="This imposing fortress, carved into the fiery core of Blackrock Mountain, represented the might of the Dark Iron clan for centuries. More recently, the black dragon Nefarian and his spawn seized the keep's upper spire and ignited a brutal war against the dwarves. The draconic armies have since allied with Warchief Rend Blackhand and his false Horde. This combined force lords over the spire, conducting horrific experiments to bolster its ranks while plotting the meddlesome Dark Irons' downfall."}
d[1584] = {name="Blackrock Depths", description="The smoldering Blackrock Depths are home to the Dark Iron dwarves and their emperor, Dagran Thaurissan. Like his predecessors, he serves under the iron rule of Ragnaros the Firelord, a merciless being summoned into the world centuries ago. The presence of chaotic elementals has attracted Twilight's Hammer cultists to the mountain domain. Along with Ragnaros' servants, they have pushed the dwarves toward increasingly destructive ends that could soon spell doom for all of Azeroth."}
d[2017] = {name="Stratholme", description="Stratholme was once the jewel of northern Lordaeron, but today it is remembered for its harrowing fall to ruin. It was here that Prince Arthas turned his back on the noble paladin Uther Lightbringer, slaughtering countless residents believed to be infected with the horrific plague of undeath. Ever since, cursed Stratholme has been marred by death, betrayal, and hopelessness."}
d[2057] = {name="Scholomance", description="Individuals seeking to master the powers of undeath know well of Scholomance, the infamous school of necromancy located in the dark and foreboding crypts beneath Caer Darrow. In recent years, several of the instructors have changed, but the institution remains under the control of Darkmaster Gandling, a particularly sadistic and insidious practitioner of necromantic magic."}
d[2100] = {name="Maraudon", description="According to legend, Zaetar, son of Cenarius, and the earth elemental princess Theradras begot the barbaric centaur race. Shortly after the centaur's creation, the ruthless creatures murdered their father. The grief-stricken Theradras is said to have trapped her lover's spirit within Maraudon, corrupting the region. Now, vicious centaur ghosts and twisted elemental minions roam every corner of the sprawling caves."}
d[2437] = {name="Ragefire Chasm", description="Ragefire Chasm extends deep below the city of Orgrimmar. Barbaric troggs and devious Searing Blade cultists once plagued the volcanic caves, but now a new threat has emerged: dark shaman. Although Warchief Garrosh Hellscream recently called on a number of shaman to use the elements as weapons against the Alliance, the chasm's current inhabitants appear to be renegades. Reports have surfaced that these shadowy figures are amassing a blistering army that could wreak havoc if unleashed upon Orgrimmar."}
d[2557] = {name="Dire Maul", description="Built thousands of years ago to house the kaldorei's arcane secrets, the formerly great city of Eldre'Thalas now lies in ruin, writhing with warped, twisted forces. Competing covens once fought for control of Dire Maul's corrupted energy, but they have since settled into uneasy truces, choosing to exploit the power within their own territories rather than continue to battle over the entire complex."}
d[16544] = {name="City of Dalaran", description="The Magic barrier around Dalaran has fallen, and the city of mages is overrun. Once the seat of the Kirin Tor and their great libraries, it was ravaged in the Third War by Arthas and then destroyed by Archimonde. Clear out the threats that remain."}
d[16550] = {name="The Drowned City", description="The fabled lost troll city of I'lalai is finally found. The last trolls live there among the Saltseer Pirates, and the magical corruption of the Kurzen Compounds has spread through it. Adventurers must stop the dangers within."}
d[16554] = {name="Blackmaw Hold", description="The Blackmaw furbolgs, rivals of the Timbermaw clan, have made a pact with the demonic Legashi satyrs. Together they are corrupting Azshara with fel magic from their stronghold, Blackmaw Hold. Help the Timbermaw put a stop to them."}
d[16611] = {name="Ruins of Lordaeron", description="The ruins of Lordaeron still hold the Scourge from the Third War, haunting the Forsaken of Tirisfal Glades. Push back the Lich King's army from the ruined capital before it spreads further."}
d[16620] = {name="Alcaz Prison", description="A hidden prison on Alcaz Island in Dustwallow Marsh. After Theramore members aligned with the Defias Brotherhood, the missing King Varian Wrynn is believed to be held here. The Alliance seeks its lost king while others have their own plans for the prison."}
d[16667] = {name="The Shaper's Terrace", description="A terrace of the Shapers, a forgotten people, in Un'Goro Crater. Their old workings hold the threats that now stir in the crater."}
d[16732] = {name="Excavation Site: Wetlands", description="The Explorer's League, archaeologists studying the origins of the dwarven race, has a camp in the Wetlands at Whelgar's Excavation Site, overrun with raptors. Strange activity to the southeast has revealed a titan site, and a new camp was set up to explore it."}
d[16842] = {name="Krol'dok Stronghold", description="The capital of the Krol'dok ogre clan rises over the Riverglades. The ogres are joined by the Twilight's Hammer and the Shadowhide gnolls, who want to take the Riverglades from the Bolderok ogres and the Brotherhood of the Horse."}
d[16919] = {name="The Hall of Thanes", description="Hidden beneath the High Seat of Ironforge, the Hall of Thanes is the resting place of the legendary dwarves of the Eastern Kingdoms. Now the Dark Iron dwarves have invaded it, and it is part of the old Ironforge that was sealed away until Forever."}
b["akumai"] = {description="Aku'mai, an ancient evil, carries within him a small measure of the Old Gods' power. This three-headed hydra is greatly feared for his mindless savagery and insatiable hunger for living flesh, but the Twilight's Hammer worships him as a divine sign that the Old Gods will soon return.", abilities={}}
b["alzzin the wildshaper"] = {description="Alzzin the Wildshaper seeks nothing less than the total corruption of Feralas, but until he discovered the Shrine of Eldretharr in Dire Maul, he had little success. With the power of enslaved ancients at his command, Alzzin concentrated the vitality of the surrounding forest into his lair, allowing him to manipulate it at will.", abilities={{name="Enervate", text="Alzzin the Wildshaper saps a player, draining mana.", spellID=22661, icon=132105}, {name="Wither", text="Alzzin the Wildshaper inflicts Nature damage to a player and leaves a withering disease, inflicting more Nature damage over time and reduces...", spellID=22662, icon=136066}, {name="Thorns", text="Alzzin the Wildshaper covers himself in Thorns, inflicting Nature damage to all players that attack Alzzin the Wildshaper.", spellID=22351, icon=136104}, {name="Tree Form", text="Alzzin the Wildshaper transforms into a Tree, increasing his armor and increasing his melee damage.", spellID=22688, icon=132129}}}
b["ambassador flamelash"] = {description="For his unwavering service to Ragnaros, Flamelash ascended to the rank of ambassador to the Dark Iron clan. This depraved being initially despised his dwarven allies, but he has come to respect their penchant for destruction. As a show of solidarity, Flamelash guards the Chamber of Enchantment, a sacred location used by the dwarves to empower their weaponry.", abilities={{name="Burning Spirit", text="Burning Spirits will sacrifice themselves to give Burning Spirit to Ambassador Flamelash when they get within 1 yard of him.", spellID=14744, icon=135805}, {name="Fire Blast", text="Ambassador Flamelash inflicts Fire damage to players he hits in melee.", spellID=15574, icon=135817}}}
b["amnennar the coldbringer"] = {description="The lich Amnennar was once a force of reckoning within the Scourge, participating in the assault on Mount Hyjal during the Third War. Afterward, the Lich King instructed his servant to remain in Kalimdor and expand the Scourge's influence. This effort was thwarted by heroes of the Horde and Alliance, however. Now the relative peace that has been brought to Razorfen Downs may be threatened. Death Speaker Blackthorn hopes to revive this powerful lich and renew the assault on the Barrens.", abilities={}}
b["ancient stone keeper"] = {description="One of many golems that staffed and operated the great titan vault, the Ancient Stone Keeper was part of a small group that served as an intermediary between the watchers left in control of the facility and their many servants. With the corruption of the Obsidian Sentinel, the Ancient Stone Keeper is the last of its kind, performing its duty by protecting the secrets of the titans as best it can until its inevitable shutdown.", abilities={{name="Sand Storms", text="Ancient Stone Keeper summons a sand storm that moves towards a player, inflicting physical damage and reducing movement speed of all players...", spellID=10093, icon=136022}}}
b["antusul"] = {description="Antu'sul prefers his sul'lithuz basilisks strong and ruthless. He treats these scaled beasts like family, and he is known to strike down anyone--even fellow trolls--who harm his precious children. Rather than give his opponents a proper burial, Antu'sul allows the basilisks to feast on whoever dares cross him.", abilities={{name="Healing Wave", text="Antu'sul heals an ally.", spellID=15982, icon=136052}, {name="Healing Ward", text="Antu'sul summons a Greater Healing Ward at his feet. The Greater Healing Ward heals all of Antu'sul's allies nearby for until destroyed.", spellID=11899, icon=135928}, {name="Earthgrab Totem", text="Antu'sul summons an Earthgrab Totem at his feet. The Earthgrab Totem immobilizies all players nearby for until destroyed.", spellID=8376, icon=136064}, {name="Earth Shock", text="Antu'sul shocks a player, inflicting Nature damage and interrupting spellcasting.", spellID=15501, icon=136026}}}
b["archaedas"] = {description="Deep within Uldaman is a chamber containing one of the greatest treasures of the titans, created by Norgannon himself. However, thus far no explorers have managed to gain access to the relic, for any attempt at doing so activates the great watcher Archaedas, an immense guardian who easily dispatches treasure seekers through his powerful attacks and a veritable army of servants. Crafted from some of the oldest, strongest stone taken from Uldaman's depths, Archaedas is a foe as formidable as he is ancient.", abilities={{name="Awaken Earthen Dwarf", text="Archaedas awakens an Earthen Custodian every 10 seconds to assist him in battle.", icon=254108}, {name="Awaken Earthen Guardian", text="When Archaedas reaches 66% health remaining, he awakens the 6 Earthen Guardians.", icon=432002}, {name="Awaken Vault Warder", text="When Archaedas reaches 33% health remaining, he awakens the 2 Vault Warders.", icon=399040}, {name="Ground Tremor", text="Archaedas shakes the ground, stunning all enemies nearby.", spellID=6524, icon=136025}}}
b["archivist galford"] = {description="Galford once took great pride in caring for the Crusade's most valued documents. However, as he lay dying, he watched in horror as his precious tomes were burnt around him. Balnazzar used this painful memory to imbue his servant with the fiery power that ravaged Galford in life.", abilities={{name="Fire Nova", text="Instructor Galford unleashes a fire nova, inflicting Fire damage to all enemies nearby.", spellID=17366, icon=135824}, {name="Pyroblast", text="Instructor Galford inflicts Fire damage to his current target.", spellID=33975, icon=135808}, {name="Burning Winds", text="Instructor Galford envelopes his current target in burning wind, inflicting Fire damage and stunning them.", spellID=17293, icon=136018}}}
b["avatar of hakkar"] = {description="Hakkar was notorious for demanding sacrifices from his followers. Many millennia ago, he instructed the Atal'ai to bring forth his avatar, using blood ritually drained from living victims to feed him. The Atal'ai priests now seek to raise Hakkar's avatar with a modified version of this ritual, one that involves sacrificing green dragons. If the Atal'ai succeed, the re-emergence of Hakkar's avatar could spell doom for Azeroth.", abilities={{name="Cause Insanity", text="The Avatar of Hakkar drives a player insane, causing them to attack their own allies.", spellID=12888, icon=136206}, {name="Curse of Tongues", text="The Avatar of Hakkar curses a player, reducing their casting speed.", spellID=12889, icon=136140}, {name="Lash", text="The Avatar of Hakkar lashes out at his current target, stunning them. In addition, Lash has a 10% chance of disarming its target.", spellID=6607, icon=132109}}}
b["baelgar"] = {description="The monstrous molten giant Bael'Gar lumbers across the Dark Iron Highway, a stunning feat of dwarven engineering carved into Blackrock Depths. Ragnaros pulled the giant from the heart of the Firelands to guard a massive sealed door at one end of the highway. According to legend, only the Firelord and the Dark Iron clan's highest-ranking members know what lies beyond the mysterious gate.", abilities={{name="Magma Splash", text="Players who strike Bael'Gar with melee attacks will suffer Fire Damage. Magma Splash stacks several times.", spellID=23379, icon=135817}, {name="Summon Spawn of Bael'Gar", text="Bael'Gar inflicts Fire damage to all players in a random location and summons a Spawn of Bael'Gar that will aid him in battle.", icon=135819}}}
b["baelog"] = {description="Seeking fame, more importantly, fortune, the three brothers Eric, Olaf, and Baelog took on a contract from the Explorers' League to delve deep into the halls of Uldaman and clear a path for a group of researchers. For these three dwarves, however, \"clearing a path\" unfortunately entailed \"getting hopelessly lost in an ancient labyrinth.\" Proud dwarves to the end, they fight to prevent the secrets of Uldaman and the Explorers' League from falling into the hands of the Horde.", abilities={{name="Strike", text="Baelog strikes his current target, inflicting Physical damage.", icon=132282}, {name="Shoot", text="Baelog shoots a player, inflicting Physical damage.", icon=132222}}}
b["balnazzar"] = {description="Balnazzar has never tasted true death, but he has suffered bitter defeat. After the Cataclysm rocked the world, he slaughtered the Scarlet Crusaders in Stratholme and transformed them into the undead creatures they once hated. The dreadlord now plots his machinations for vengeance upon Azeroth.", abilities={{name="Mind Blast", text="Balnazzar inflicts Shadow damage to his current target.", spellID=80750, icon=136224}, {name="Shadow Shock", text="Balnazzar inflicts Shadow damage to all players nearby.", spellID=452927, icon=136197}, {name="Domination", text="Balnazzar takes control of a random player.", spellID=17405, icon=136206}, {name="Sleep", text="Balnazzar forces a random player to sleep, stunning them or until they take damage.", spellID=452928, icon=136090}}}
b["baron silverlaine"] = {description="Baron Silverlaine was master of the keep before it fell to Arugal's worgen. Now his cursed spirit calls upon the very wolf-beasts that slaughtered him to punish further trespassers into his home.", abilities={{name="Veil of Shadow", text="Baron Silverlaine curses his current enemy target, reducing magical healing effects done to the target.", spellID=23224, icon=136160}, {name="Summon Worgen Spirit", text="Baron Silverlaine summons one of four random Worgen Spirits from the past at 70% and 35% health: Odo the Blindwatcher, Razorclaw the...", icon=366940}}}
b["baroness anastari"] = {description="While she lived, Anastari took what she wanted, no matter the cost. Death has done little to change. Her soul ripped from her body, Anastari became a banshee, and she has abandoned her love of material trinkets in favor of possessions of a far more sinister kind.", abilities={{name="Possess", text="Baroness Anastari takes control of a random player. Possess increases the target's maximum health and damage dealt, but reduces their...", spellID=17244, icon=136129}, {name="Banshee Wail", text="Baroness Anastari wails with anguish, inflicting Shadow damage to her current target.", spellID=16868, icon=136197}, {name="Silence", text="Baroness Anastari silences all players nearby, preventing spell casting.", spellID=18327, icon=135975}, {name="Banshee Curse", text="Baroness Anastari curses all players nearby, reducing their chance to hit.", spellID=16867, icon=136020}}}
b["blind hunter"] = {description="After years of seclusion, a monstrous creature from deep inside the dark grotto emerged. This gargantuan bat continually feeds on the boar once named Agathelos the Raging, whose dark power was once fueled by continual consumption of bat guano.", abilities={}}
b["cannon master willey"] = {description="Balnazzar took great pleasure in leveraging the cannon master Willey's destructive capabilities in undeath, calling his prized minion by the name of Hopebreaker. The dreadlord relishes that he has twisted Willey and other Scarlet Crusaders--who so despised the undead in life--into his unwitting pawns.", abilities={{name="Summon Risen Riflemen", text="Willey Hopebreaker calls for Risen Riflemen to assist him in battle every 5 sec.", icon=136075}, {name="Scarlet Cannon", text="The Scarlet Cannons near Willey Hopebreaker can be loaded with cannonballs and fired at the incoming Risen Riflemen."}, {name="Knock Away", text="Willey Hopebreaker inflicts Physical damage to his current target, knocking them away.", spellID=110762, icon=132939}, {name="Shoot", text="Willey Hopebreaker shoots his current target, inflicting Physical damage.", spellID=59146, icon=132222}}}
b["captain greenskin"] = {description="Captain of the juggernaut-in-progress, Greenskin hails from Booty Bay where he formerly led a fleet of pirate vessels.", abilities={{name="Poisoned Harpoon", text="Greenskin throws a poison-tipped harpoon at his target, inflicting Nature damage and more Nature damage over time.", spellID=5208, icon=132273}, {name="Cleave", text="Greenskin inflicts Physical damage on several enemies in front of him.", spellID=40505, icon=132338}, {name="Pistol Shot", text="Greenskin fires his pistol at a distant target, inflicting Physical damage.", spellID=450550, icon=134536}}}
b["captain kromcrush"] = {description="Even among ogres, Captain Kromcrush is infamous for his hair-trigger rage toward anyone who dares to insult him or King Gordok. He crushes dissent ruthlessly, but he has still less patience for those who continue to spread the rumor of his torrid affair with a gnoll long ago.", abilities={{name="Frightening Shout", text="Captain Kromcrush causes all players nearby to run in fear.", spellID=19134, icon=132154}, {name="Mortal Cleave", text="Captain Kromcrush inflicts Physical damage to a player and an additional player adjacent to the first.", spellID=22859, icon=132355}, {name="Retaliation", text="Captain Kromcrush retaliates against all players who strike him in melee combat, inflicting Physical damage.", spellID=22857, icon=132336}}}
b["celebras the cursed"] = {description="Upon learning of his uncle's tragic fate, the noble Celebras swore to free Zaetar's spirit. Yet the keeper of the grove was not prepared for the horrors that awaited him in Maraudon's shadowy corridors. The dark energies permeating the area quickly overcame Celebras, filling his heart with uncontrollable rage.", abilities={{name="Corrupt Force of Nature", text="Celebras the Cursed summons Corrupt Forces of Nature to aid him in battle.", spellID=21968, icon=136036}, {name="Twisted Tranquility", text="Celebras the Cursed inflicts Nature damage to all players nearby, reducing their movement speed and increasing the time between their...", spellID=21793, icon=136107}, {name="Wrath", text="Celebras the Cursed hurls a bolt of energy at his current target, inflicting Nature damage.", icon=136006}, {name="Entangling Roots", text="Celebras the Cursed entangles his current target, immobilizing them and inflicting Nature damage.", spellID=12747, icon=136100}}}
b["charlga razorflank"] = {description="The leader (or \"crone\") of the Razorfen tribes is Charlga Razorflank, a quilboar whose experimental and powerful Geomancy practices are second to none. Her meteoric rise to power and the rapidly increasing violence between quilboar tribesmen can only lead to one thing: war.", abilities={}}
b["chief ukorz sandscalp"] = {description="Chief Ukorz Sandscalp is obsessed with restoring his tribe to its former glory. He was raised on stories of a time when trolls lorded over their ancient lands without interference from goblins, gnomes, pirates, ogres, and other foreign interlopers. Sandscalp has called on his trusted comrade Ruuzlu to help him begin a new chapter in Sandfury history in the only way their tribe knows how: with swift and blinding violence.", abilities={{name="Wide Slash", text="Chief Ukorz Sandscalp inflicts Physical damage to all players in front of him.", icon=135271}, {name="Cleave", text="Chief Ukorz Sandscalp inflicts Physical damage on several enemies in front of him.", spellID=40505, icon=132338}, {name="Frenzy", text="Chief Ukorz Sandscalp frenzies, increasing his attack speed.", spellID=8269, icon=136224}, {name="Enrage", text="When Ruuzlu dies, Chief Ukorz enrages, increasing his damage done and his attack speed.", spellID=454632, icon=132345}}}
b["chorush the observer"] = {description="Cho'Rush doesn't usually take sides, but when Ulrok was rising to power, it was clear there was nobody who could challenge him. The king quickly appointed Cho'Rush as his chief advisor, believing that his twin heads would make him twice as resourceful as the average ogre.", abilities={}}
b["commander springvale"] = {description="A loyal soldier, the ghost of Commander Springvale haunts the council room, using unholy strikes to avenge his lord, Baron Silverlaine.", abilities={{name="Malefic Strike", text="Commander Springvale slashes at his main target, instantly dealing part of his normal Physical melee damage and generating a charge of...", spellID=93685, icon=237530}, {name="Shield of the Perfidious", text="When Commander Springvale has three charges of Unholy Power, he consumes the charges and unleashes the power from his shield.", spellID=93722, icon=132390}, {name="Desecration", text="Commander Springvale desecrates the ground nearby under a random player. All players standing in this defiled ground have their movement...", spellID=93691, icon=136199}}}
b["cookie"] = {description="No one except Edwin VanCleef knows how or why Cookie was promoted to be the ship's cook. For pirates, though, a meal is a meal.", abilities={{name="Cookie's Cooking", text="Cookie takes a sip of yesterday's soup, restoring part of his health.", spellID=5174, icon=135915}, {name="Acid Splash", text="Cookie tosses a bottle of poison at his target, inflicting Nature damage.", spellID=6306, icon=132793}}}
b["crowd pummeler 9 60"] = {description="In Gnomeregan's heyday, inventors would compete for status by pitting their creations against one another. The mekgineer Oglethorpe Obnoticus built an unbeatable robot, and this earned him respect in the high tinker's court. Sicco Thermaplugg stole Obnoticus's blueprints and then made a giant version of the machine. He set his forgery loose, and the horrific results drove the ruling council to banish the innocent Obnoticus. The Crowd Pummeler 9-60 is still one of Thermaplugg's favorite (stolen) inventions.", abilities={{name="Arcing Smash", text="Crowd Pummeler 9-60 lashes out in a vicious arc, inflicting Physical damage to players in front of it.", icon=132338}, {name="Crowd Pummel", text="Crowd Pummeler 9-60 pummels players nearby, inflicting Physical damage and interrupting spell casting.", spellID=10887, icon=132938}, {name="Trample", text="Crowd Pummeler 9-60 tramples players nearby, inflicting Physical damage.", spellID=5568, icon=136063}}}
b["darkmaster gandling"] = {description="Course: Advanced Studies. The recent defeat in Andorhal has put Darkmaster Gandling in the foulest of moods. More than ever, all students of Scholomance are advised to impress him at every turn. Pupils who dissatisfy the headmaster will be removed from class to perform lab work... or become lab work.", abilities={{name="Incinerate", text="Gandling deals Fire damage to his current target.", spellID=113136, icon=135789}, {name="Immolate", text="Gandling burns an enemy for Fire damage, then inflicts more Fire damage over time.", spellID=113141, icon=133724}, {name="Rise!", text="Gandling summons a legion of Failed Students to fight for him. The students swarm the area, fighting anything they can.", spellID=113143, icon=237511}, {name="Harsh Lesson", text="Darkmaster Gandling teleports a random player to one of his study rooms for a harsh lesson!", icon=133733}}}
b["dreamscythe"] = {description="Four promising young drakes accompanied Eranikus into the Temple of Atal'Hakkar, eager to prove themselves by serving a great and powerful wyrm. One by one, they were captured and tainted by the Emerald Nightmare, and they now wander the halls of the Sunken Temple, lashing out at all who intrude upon their waking dream.", abilities={{name="Acid Breath", text="The Wardens of the Dream breath acid, inflicting Nature damage instantly and additional Nature damage to all players in front of them.", spellID=12884, icon=136007}, {name="Wing Flap", text="The Wardens of the Dream thrash their wings, knocking all players in front of them backwards.", icon=136022}}}
b["edwin vancleef"] = {description="Formerly the leader of the Stonemasons Guild, disputes with the House of Nobles led VanCleef to leave Stormwind City and create the Defias Brotherhood. VanCleef then claimed the Deadmines as a base of operations to construct the juggernaut that would begin his retribution.", abilities={{name="Rupture", text="VanCleef stabs his target, inflicting Physical damage.", spellID=14874, icon=132302}, {name="Shadowstep", text="VanCleef steps into the shadows, reappearing behind a random enemy and stabbing them in the back for Physical damage.", spellID=15657, icon=132303}, {name="VanCleef's Allies", text="At 50% health, VanCleef calls for aid from nearby thugs in the shadows.", icon=132299}}}
b["electrocutioner 6000"] = {description="Mekgineer Thermaplugg is not a patient gnome. Rather than putting his inventions through a battery of tests to determine their safety and effectiveness, he rushes them into the field and moves on to the next project. The Electrocutioner 6000 was his first attempt at harnessing electricity as a weapon via a super-charged mechano-tank. Lieutenant Tom \"Sizzlepants\" Crankle, the only soldier to survive piloting the Electrocutioner, is now something of a hero among the leper gnomes.", abilities={{name="Megavolt", text="Electrocutioner 6000 inflicts Nature damage to all players in front of him.", icon=136015}, {name="Shock", text="Electrocutioner 6000 throws a bolt of lightning at his current target, inflicting Nature damage.", spellID=11084, icon=136115}, {name="Chain Bolt", text="Electrocutioner 6000 strikes his current target with a lightning bolt that arcs to nearby targets, inflicting Nature damage to each target.", spellID=11085, icon=136015}}}
b["emperor dagran thaurissan"] = {description="Emperor Dagran Thaurissan rules alongside Princess Moira of the rival Bronzebeard clan. Debate rages over whether the emperor ensorcelled his bride or she willingly joined him. Whatever the truth, Thaurissan's continued presence bodes ill for the future of his clan. So long as he lives, the Dark Irons will remain pawns of Ragnaros, and a dire threat to kingdoms throughout Azeroth.", abilities={{name="Avatar of Flame", text="Emperor Dagran Thaurissan becomes an Avatar of Flame. The Avatar of Flame is immune to all magic and inflicts Fire damage whenever he...", spellID=15636, icon=135818}, {name="Ironfoe", text="Emperor Dagran Thaurissan carries the mighty hammer, Ironfoe. Emperor Dagran Thaurissan's melee attacks have a chance to trigger extra...", spellID=15642, icon=135873}, {name="Hand of Thaurissan", text="Emperor Dagran Thaurissan inflicts Fire damage to a player and stuns them.", spellID=17492, icon=135807}, {name="Heal", text="Princess Moira Bronzebeard calls upon Holy magic to heal an ally.", icon=135915}}}
b["eric the swift"] = {description="Seeking fame, more importantly, fortune, the three brothers Eric, Olaf, and Baelog took on a contract from the Explorers' League to delve deep into the halls of Uldaman and clear a path for a group of researchers. For these three dwarves, however, \"clearing a path\" unfortunately entailed \"getting hopelessly lost in an ancient labyrinth.\" Proud dwarves to the end, they fight to prevent the secrets of Uldaman and the Explorers' League from falling into the hands of the Horde.", abilities={{name="Rushing Charge", text="Eric \"The Swift\" charges towards a player, increasing the damage of his next attack.", icon=132368}}}
b["fineous darkvire"] = {description="Chief Architect Fineous Darkvire earned his title by passing off the ideas of more gifted masons as his own. His arrogance and scheming have drawn the ire of his predecessor, Franclorn Forgewright, from beyond the grave. The ghost of the late chief architect seeks to reclaim his incredibly powerful hammer--Ironfel--from Darkvire before it can be used for ill.", abilities={{name="Holy Strike", text="Fineous Darkvire inflicts Holy damage to a player.", icon=132325}, {name="Devotion Aura", text="Devotion Aura increases the armor of Fineous Darkvire and any allies nearby by 1080.", spellID=8258, icon=135893}, {name="Holy Light", text="Fineous Darkvire heals himself or one of his allies.", icon=135920}, {name="Kick", text="Fineous Darkvire inflicts Physical damage to a player and interrupts any spell being cast.", icon=132219}}}
b["gahzrilla"] = {description="Legend has it that Gahz'rilla was an adored pet of the Old Gods, or even a demigod in her own right. Whatever the truth is, the Sandfury trolls have worshiped this monstrous hydra for thousands of years. Ever wary of the beast's icy wrath, the trolls will only rouse Gahz'rilla when they have plentiful sacrifices to sate the ravenous creature's appetite.", abilities={{name="Icicle", text="Gahz'rilla shoots a bolt of ice, inflicting Frost damage to a random player and slowing their movement speed.", spellID=11131, icon=135846}, {name="Freeze Solid", text="Gahz'rilla freezes a player, stunning them and inflicting Frost damage.", spellID=11836, icon=135852}, {name="Gahz'rilla Slam", text="Gahz'rilla slams the ground, inflicting Physical damage to all players nearby and knocking them into the air.", spellID=11902, icon=132111}}}
b["galgann firehammer"] = {description="Reacting to the discovery of Uldaman by Bronzebeard dwarves, the Dark Iron clan mounted an invasion of the vault to stop their ancestral foes from accessing the powerful artifacts within. Galgann Firehammer, a senator from Shadowforge City, was sent to oversee the continued excavation of Uldaman so that the emperor may harness the artifacts' destructive potential against the Dark Irons' enemies.", abilities={{name="Fire Nova", text="Galgann Firehammer inflicts Fire damage to all players nearby.", spellID=11969, icon=135824}, {name="Flame Lash", text="Galgann Firehammer burns a player, inflicting Fire damage and reducing their Fire resistance. This effect stacks up to 3 times.", spellID=3356, icon=135807}, {name="Amplify Flames", text="Galgann Firehammer increases the damage his current target takes from Fire.", spellID=9482, icon=135807}, {name="Flame Spike", text="Shadowforge Geologist calls down a pillar of flame, inflicting Fire damage to all players nearby of the targeted area and more Fire damage...", spellID=8814, icon=135826}}}
b["general angerforge"] = {description="Through a lifetime of study, General Angerforge has become an expert on dwarven military history and tactics. He recently incurred Emperor Dagran Thaurissan's fury by writing a scathing treatise on his clan's failures in past conflicts. This political blunder aside, Angerforge is a Dark Iron to his core. He will bleed--and die, if necessary--to protect his people and his emperor.", abilities={{name="Sunder Armor", text="General Angerforge reduces the armor of a player, increasing the physical damage they take.", spellID=15572, icon=132363}, {name="Flurry", text="General Angerforge gains melee haste each time he critically strikes a player. Flurry can stack up to 3 times.", spellID=17687, icon=132152}, {name="Enrage", text="General Angerforge Enrages each time he is critically struck by a melee attack. Enrage increases the Physical damage General Angerforge...", spellID=15061, icon=136224}}}
b["ghamoo ra"] = {description="When the Twilight's Hammer cult arrived, its followers roused and imprisoned one of the last peaceful creatures living in Elune's temple. The cult delighted in tormenting the giant turtle for years, flaying its mind and body until it succumbed to madness. Naming the beast Ghamoo-Ra, the cultists attempt to control its savagery in order to protect their lair.", abilities={}}
b["gilnid"] = {description="Gilnid is a masterful engineer and head smelter of the Defias Brotherhood's operations. He ensures the juggernaut is loaded with sufficient cannons and ammunition and will tolerate no breaks until the work is complete.", abilities={{name="Molten Metal", text="Gilnid hurls molten metal, inflicting Fire damage to an enemy, increasing the time between their attacks, and slowing their movement.", spellID=5213, icon=135807}, {name="Melt Ore", text="Gilnid covers nearby enemies in molten ore, inflicting Fire damage and reducing their movement speed. This effect stacks.", spellID=5159, icon=135826}, {name="Summon Remote-Controlled Golems", text="Gilnid calls out worker golems to attack a random target.", spellID=450542, icon=132281}}}
b["gizrul the slavener"] = {description="Very few of the Dark Horde have seen the reclusive and unpredictable Gizrul. The beast emerges from his shadowy den only when his mate, Halycon, calls to him. The two monstrous creatures have produced some of the largest--and most ferocious--worgs ever bred in orcish history.", abilities={{name="Frenzy", text="Gizrul the Slavener goes into a frenzy, increasing his attack speed.", spellID=8269, icon=136224}, {name="Fatal Bite", text="Gizrul the Slavener bites his current target, inflicting Physical damage and draining health.", icon=132090}, {name="Infected Bite", text="Gizrul the Slavener bites his current target, inflicting Nature damage and increasing their Physical damage taken.", spellID=16128, icon=136127}}}
b["golem lord argelmach"] = {description="Argelmach's lifelong obsession with immortality drove him to forge enchanted constructs in his own image. Rumor has it that he has also dabbled in some form of black magic that would allow the golem lord's new creations to act as vessels for his spirit should his flesh-and-blood body be destroyed.", abilities={{name="Chain Lightning", text="Golem Lord Argelmach inflicts Nature damage to a player. Chain Lightning jumps to a nearby player within 15 yards and inflicts Nature damage...", spellID=15305, icon=136015}, {name="Shock", text="Golem Lord Argelmach inflicts Nature damage to a player.", icon=136115}, {name="Lightning Shield", text="Golem Lord Argelmach surrounds himself with balls of lightning. There is a chance that the Lightning Shield will retaliate against any...", spellID=15507, icon=136051}}}
b["grimlok"] = {description="In trogg society, the biggest, strongest, and most vicious trogg often becomes chieftain through displays of power. Grimlok is a comparative genius in that he has maintained control of the Stonevault troggs through intimidation and what might be considered crude psychological warfare. Having trained a deadly basilisk, Grimlok uses the threat of petrification by his beast to keep any would-be usurpers in line.", abilities={{name="Chain Bolt", text="Grimlok strikes his target with a lightning bolt that arcs to nearby players, inflicting Nature damage to targets.", spellID=8292, icon=136015}, {name="Lightning Bolt", text="Grimlok blasts his current target with lightning, inflicting Nature damage.", icon=136048}, {name="Bloodlust", text="Grimlok increases one of his ally's attack speed.", spellID=6742, icon=136012}, {name="Shrink", text="Grimlok shrinks all players nearby, reducing their Strength and Stamina.", spellID=11892, icon=136121}}}
b["grubbis"] = {description="The radioactive gas that flooded the city was meant to anger the troggs and kill the gnomes, and Thermaplugg's plan was brutally effective. One trogg, however, reacted oddly to the substance: Grubbis grew. And grew. It was a side effect that Sicco had not anticipated, but he's never been one to waste valuable (and dangerous) resources. This giant trogg now patrols the tunnels of Gnomeregan. His loyal basilisk pet, Chomper, helps Grubbis sniff out gas leaks, tasty fungi, and even tastier intruders.", abilities={{name="Strike", text="Grubbis inflicts Physical damage to his current target.", icon=132282}, {name="Chomper", text="Chomper fights alongside Grubbis."}}}
b["guard fengus"] = {description="Ever since Cho'Rush the Observer told him he was destined to meet a mate while on duty, Fengus has spent almost every waking moment patrolling Gordok territory.", abilities={{name="Shield Bash", text="Guard Fengus inflicts Physical damage to a player and interrupts any spell being cast.", spellID=11972, icon=132357}, {name="Shield Charge", text="Guard Fengus charges a player, knocking them back and inflicting Physical damage to them.", icon=132337}, {name="Strike", text="Guard Fengus inflicts Physical damage to a player.", icon=132282}, {name="Frenzy", text="Guard Fengus attacks faster.", spellID=8269, icon=136224}}}
b["guard moldar"] = {description="Mol'dar is a zealously loyal guard from the Gordok ogres. He is convinced King Gordok gifted him with a pair of enchanted gauntlets that have enabled him to become his people's arm wrestling champion for six years running. In truth, King Gordok threw the powerful armor away; Mol'dar simply found it first.", abilities={{name="Shield Bash", text="Guard Mol'dar inflicts Physical damage to a player and interrupts any spell being cast.", spellID=11972, icon=132357}, {name="Shield Charge", text="Guard Mol'dar charges a player, knocking them back and inflicting Physical damage to them.", icon=132337}, {name="Strike", text="Guard Mol'dar inflicts Physical damage to a player.", icon=132282}, {name="Frenzy", text="Guard Mol'dar attacks faster.", spellID=8269, icon=136224}}}
b["guard slipkik"] = {description="Some might think Slip'kik is merely cautious, but he's also lazy. Rather than challenge King Gordok directly, Slip'kik tinkers with traps and old, broken magical devices, hoping to eventually deliver a coup de grace without an ounce of risk or a drop of sweat.", abilities={{name="Shield Bash", text="Guard Slip'kik inflicts Physical damage to a player and interrupts any spell being cast.", spellID=11972, icon=132357}, {name="Shield Charge", text="Guard Slip'kik charges a player, knocking them back and inflicting Physical damage to them.", icon=132337}, {name="Strike", text="Guard Slip'kik inflicts Physical damage to a player.", icon=132282}, {name="Frenzy", text="Guard Slip'kik attacks 60% faster.", spellID=8269, icon=136224}}}
b["halycon"] = {description="Halycon comes from a long line of great worgs bred for their ferocity and loyalty. Over the years, the den mother has produced an astonishing number of savage offspring. Rumors have spread that she is a demonic hound gifted to Rend Blackhand by a pit lord of the Burning Legion.", abilities={{name="Thrash", text="Halycon thrashes at her current target, attacking additional times.", spellID=3391, icon=132152}, {name="Rend", text="Halycon rends her current target, inflicting Physical damage", spellID=13738, icon=132155}}}
b["hazzas"] = {description="Four promising young drakes accompanied Eranikus into the Temple of Atal'Hakkar, eager to prove themselves by serving a great and powerful wyrm. One by one, they were captured and tainted by the Emerald Nightmare, and they now wander the halls of the Sunken Temple, lashing out at all who intrude upon their waking dream.", abilities={{name="Acid Breath", text="The Wardens of the Dream breath acid, inflicting Nature damage instantly and additional Nature damage to all players in front of them.", spellID=12884, icon=136007}, {name="Wing Flap", text="The Wardens of the Dream thrash their wings, knocking all players in front of them backwards.", icon=136022}}}
b["hearthsinger forresten"] = {description="The Culling of Stratholme claimed the lives of innumerable people whose only crime was being in the doomed city. A traveling singer and piccolo player named Forresten was one such victim. He continues to wander the city in death, unable to accept his tragic fate.", abilities={{name="Enchanting Lullaby", text="Hearthsinger Forresten lulls a player to sleep, stunning them or until they take damage.", spellID=16798, icon=136209}, {name="Demoralizing Shout", text="Hearthsinger Forresten shouts, reducing the Stamina and primary stats of all players nearby.", spellID=16244, icon=132366}, {name="Incorporeal Defense", text="Hearthsinger Forresten's chance to dodge attacks is increased by 50%.", icon=135991}, {name="Multi-Shot", text="Hearthsinger Forresten inflicts Physical damage to several players in front of him.", spellID=20735, icon=132330}}}
b["high inquisitor whitemane"] = {description="At a young age, Sally Whitemane witnessed her family succumb to the horrific plague of undeath as they were traveling through northern Lordaeron. She was then forced to destroy her parents and siblings when they rose as mindless Scourge minions, leaving her racked by guilt and rage. Ever since that day, the fearsome priestess has found fulfillment and pleasure in only one thing: the destruction of undead.", abilities={{name="Power Word: Shield", text="High Inquisitor Whitemane wraps an ally in a magical shield that absorbs damage.", spellID=22187, icon=135940}, {name="Holy Smite", text="High Inquisitor Whitemane smites her current target, inflicting Holy damage.", spellID=114848, icon=135924}, {name="Mass Resurrection", text="High Inquisitor Whitemane resurrects all fallen Scarlet Judicators within 100 yards to come to her aid.", icon=413586}}}
b["high interrogator gerstahn"] = {description="The Twilight's Hammer cultist Gerstahn has always indulged in life's finer things: exotic foods, fine clothes, and gem-encrusted torture tools. Day and night, her prisoners' bloodcurdling cries echo throughout the Dark Iron clan's infamous Detention Block. Gerstahn proudly calls this horrific noise her symphony of screams, and she is always eager to add another voice to the chorus.", abilities={{name="Mana Burn", text="High Interrogator Gerstahn inflicts Shadow damage to a player and drains a portion of their mana.", icon=136170}, {name="Psychic Scream", text="High Interrogator Gerstahn causes all players nearby to run in fear.", spellID=13704, icon=136184}, {name="Shadow Word: Pain", text="High Interrogator Gerstahn inflicts a player with Shadow Word: Pain. Shadow Word: Pain inflicts Shadow damage.", spellID=14032, icon=136207}, {name="Shadow Shield", text="High Interrogator Gerstahn surrounds herself in a dark shield, absorbing several damage.", spellID=12040, icon=136121}}}
b["highlord omokk"] = {description="Omokk rules over the spire's ogres with an iron fist. Many underlings have challenged him to single combat in the hopes of seizing the highlord's title, but all have fallen without landing a solitary blow. This mysterious phenomenon has led to rumors that dark magic is protecting Omokk.", abilities={{name="Knock Away", text="Highlord Omokk inflicts Physical damage to his current target, knocking them away.", icon=132939}, {name="Frenzy", text="When Highlord Omokk reaches 50% remaining health, he goes into a frenzy, increasing his attack speed.", spellID=8269, icon=136224}}}
b["houndmaster grebmar"] = {description="Grebmar Fleabeard's hounds are the only family he's ever known. Long ago, the orphaned dwarf began breeding canines to serve as companions and guard dogs. When the houndmaster isn't patrolling Blackrock Depths with his loyal beasts, he often treats them to the Grim Guzzler's finest Dark Iron ale.", abilities={{name="Dual Wield", text="Houndmaster Gremar wields a weapon in each hand.", icon=132147}, {name="Demoralizing Shout", text="Houndmaster Grebmar reduces the attack power of all players nearby.", spellID=13730, icon=132366}, {name="Pummel", text="Houndmaster Grembar inflicts Physical damage to a player and interrupts any spell casting.", spellID=15615, icon=132938}, {name="Bloodlust", text="Houndmaster Grebmar sends an ally into a frenzy, increasing their attack speed.", spellID=21049, icon=136012}}}
b["hurley blackbreath"] = {description="To say Blackbreath is a regular at the Grim Guzzler would be something of an understatement. In over a decade, the mischievous drunkard has left the tavern only once to steal a top-secret recipe for Thunderbrew Lager. Blackbreath has occasionally sobered up enough to make the concoction himself, and he claims it grants unimaginable strength and courage.", abilities={{name="Flame Breath", text="Hurley Blackbreath inflicts Fire damage to all players in a cone in front of him.", icon=135805}, {name="Drunken Rage", text="Hurley Blackbreath increases his attack speed and his Physical damage is increased.", spellID=14872, icon=136224}}}
b["hydromancer velratha"] = {description="Unlike most of the Sandfury trolls, Hydromancer Velratha has traveled the world, collecting knowledge and artifacts to help her command Zul'Farrak's sacred waters. Although the hydromancer's actions have earned her many enemies abroad, she sees the incredible power at her command as justification for her past misdeeds.", abilities={{name="Healing Wave", text="Hydromancer Velratha heals an ally.", spellID=15982, icon=136052}, {name="Water Bolt", text="Hydromancer Velratha hurls a watery bolt at a player, inflicting Frost damage.", spellID=78801, icon=135845}, {name="Crashing Wave", text="Hydromancer Velratha summons a typhoon that inflicts Frost damage to all players in front of her and knocks them back.", spellID=78802, icon=236170}}}
b["hydrospawn"] = {description="When the satyr Zevrim Thornhoof sought to control the elementals in Dire Maul, he focused on Hydrospawn, who calmly resided in the pool beneath his altar. As he performed his profane sacrificial rituals, the elemental grew agitated and restless, striking out at Thornhoof's demonic minions. As the years passed, Thornhoof used his victims' energies to whip Hydrospawn into unbridled fury, little by little binding its will to the satyr's commands.", abilities={{name="Submersion", text="Hydrospawn reduces the Stamina of all players nearby. This effect stacks.", spellID=22420, icon=136148}, {name="Riptide", text="Hydrospawn inflicts Frost damage to all players nearby and knocks them back. Players affected by Riptide are disarmed.", spellID=22419, icon=132343}, {name="Massive Geyser", text="Hydrospawn summons a Massive Geyser that inflicts Frost damage to all players nearby and knocks them back.", spellID=22422, icon=135861}, {name="Hydrojet", text="The Hydroling has a chance to knock a player back and reduce their threat to zero whenever they strike a player in melee combat.", icon=135836}}}
b["illyanna ravenoak"] = {description="Illyanna Ravenoak, along with her faithful companion Ferra, was once Prince Tortheldrin's most valued hunter, until she refused to carry out her leader's order to execute her friends. As punishment, he killed Illyanna and her bear, but he used his demonic power to bind their spirits to their bodies, condemning them to remain in Dire Maul as undead protectors.", abilities={{name="Charge", text="Ferra charges a player, inflicting Physical damage and stunning them.", spellID=22911, icon=132337}, {name="Maul", text="Ferra inflicts Physical damage to a player.", spellID=17156, icon=132136}, {name="Multi-Shot", text="Illyanna Ravenoak inflicts Physical damage to several players in front of her.", spellID=20735, icon=132330}, {name="Volley", text="Illyanna Ravenoak shoots a raining volley of arrows to all players within an area yards wide. Volley inflicts Arcane damage.", spellID=30933, icon=132222}}}
b["immolthar"] = {description="In a desperate bid to restore the power and immortality they lost when the Well of Eternity was destroyed, the Shen'dralar summoned a demon into the western wing of Dire Maul and captured him within a force field, allowing them to use the void terror's energy for their own spells. Unable to fight back or even move for nearly 10,000 years, Immol'thar could only watch and wait for the day he might break free and rend the flesh of his captors.", abilities={{name="Gaze of Immol'thar", text="Eyes of Immol'thar slow player movement speed, reduce their Haste, and deal Shadow damage. This effect stacks.", spellID=22909, icon=136120}, {name="Portal of Immol'thar", text="Immol'thar periodically summons players to its location and reduces their threat to zero.", icon=135743}, {name="Infected Bite", text="Immol'thar bites a player and their nearest ally, inflicting Nature damage and increasing their Physical damage taken.", spellID=16128, icon=136127}, {name="Frenzy", text="Immol'thar increases its attack speed.", spellID=8269, icon=136224}}}
b["ironaya"] = {description="The titans did not construct the Uldaman complex directly, but utilized various servants to create its megalithic halls. The Pantheon entrusted the watcher Ironaya with overseeing the construction and maintenance of Uldaman, but as time passed, the once awe-inspiring vault fell to ruin. Within the map chamber, Ironaya has spent millennia in a form of stasis, analyzing the original master plan drawn up by Khaz'goroth and attempting to find a way to restore the complex to its original functionality.", abilities={{name="Arcing Smash", text="Ironaya lashes out in a vicious arc, inflicting Physical damage to all enemies in front of her.", icon=132338}, {name="Knock Away", text="Ironaya inflicts Physical damage to her current target, knocking them away.", icon=132939}, {name="War Stomp", text="Ironaya stomps, inflicting Physical damage to all enemies nearby and stunning them.", spellID=11876, icon=132091}}}
b["jammalan the prophet"] = {description="Jammal'an is the current leader of the Atal'ai, the extremist sect of priests who fanatically worship Hakkar. While in deep meditation, Jammal'an received instructions on how to resurrect Hakkar by using the blood of his draconic foes, the green dragonflight. Jammal'an and his undead bodyguard Ogom the Wretched stand ready to oppose any who would prevent Hakkar's return, though the prophet's actions may unleash upon Azeroth an even more terrible force: the Emerald Nightmare.", abilities={{name="Healing Wave", text="Jammal'an the Prophet heals an ally.", icon=136052}, {name="Flamestrike", text="Jammal'an the Prophet calls down a pillar of flame, inflicting Fire damage to all players nearby of the targeted area and more Fire damage...", spellID=12468, icon=135826}, {name="Earthgrab Totem", text="Jammal'an the Prophet summons an Earthgrab Totem at his feet. Earthgrab Totem immobilizes all players nearby", spellID=8376, icon=136064}, {name="Hex of Jammal'an", text="Jammal'an the Prophet hexes a player, increasing their damage, transforming them and causing them to attack their allies.", spellID=12480, icon=136232}}}
b["jandice barov"] = {description="Course: Advanced Illusions. Barov's spirit lurked in the recesses of Scholomance for years, but now she has taken a more active role in educating the next generation of magi. Her vast knowledge of illusions has made her both a valued educator and a dangerous opponent to anyone foolish enough to draw her ire.", abilities={{name="Wondrous Rapidity", text="Jandice rears her staff back with a flash of wondrous Arcane force, unleashing a barrage of attacks that inflict Arcane damage in a cone in...", spellID=114061, icon=135732}, {name="Whirl of Illusion", text="Jandice hides amongst multiple illusions of herself, dancing in a Whirl of Illusion that inflicts Arcane damage to all enemies", spellID=113775, icon=237566}}}
b["king gordok"] = {description="To rule the Gordok ogres, one must simply proclaim oneself king... and then destroy all who might disagree. King Gordok--then merely known as Ulrok--solidified his power by convincing a dozen of his people's strongest warriors to challenge the king at the same time. The wild melee left most of the contestants dead or wounded, and Ulrok's blade easily cut down the survivors and the battle-weary king. To this day, Gordok ogres speak in hushed tones about the \"Day of Da Blood.\"", abilities={{name="Berserker Charge", text="King Gordok charges a random player, knocking them up in the air and inflicting Physical damage.", icon=132337}, {name="Sunder Armor", text="King Gordok reduces a player's armor, increasing the physical damage they receive. Sunder Armor stacks several charges.", spellID=15572, icon=132363}, {name="Mortal Strike", text="King Gordok inflicts Physical damage on a player. Mortal Strike reduces healing received.", spellID=16856, icon=132355}, {name="War Stomp", text="King Gordok inflicts Physical damage to all players nearby and stuns them.", spellID=16727, icon=132091}}}
b["kresh"] = {description="An ancient resident of the Wailing Caverns, this giant turtle wanders the underground caves, his resilient mind unaffected by Naralex's relentless nightmares. Don't be fooled by his happy disposition; Kresh has thwarted many adventurers who longed to steal his massive shell.", abilities={{name="Crushing Bite", text="Kresh bites his current target, reducing their armor.", spellID=80362, icon=133726}}}
b["lady anacondra"] = {description="Scarletleaf was the first to volunteer for Naralex's self-appointed mission to the Barrens. After her master's nightmare shattered her mind, the young acolyte cast aside her name, now envisioning a sinister reptilian future for Azeroth.", abilities={{name="Lightning Bolt", text="Lady Anacondra hurls a bolt of lightning at her current target, inflicting Nature damage.", icon=136048}, {name="Druid's Slumber", text="Lady Anacondra puts a player to sleep. Any hostile action will awaken the target.", spellID=8040, icon=136090}, {name="Thorns Aura", text="Lady Anacondra's thorns inflict Nature damage to any player that melee attack her.", icon=136104}, {name="Healing Touch", text="Lady Anacondra heals an ally.", icon=136041}}}
b["landslide"] = {description="For years, the ancient mountain giant known as Landslide cultivated brilliant crystal gardens in Maraudon, but Theradras enthralled the behemoth when she took up residence there. This once-stoic giant now lives only to serve his tyrannical new master.", abilities={{name="Knock Away", text="Landslide inflicts Physical damage to his current target, knocking them back.", icon=132939}, {name="Trample", text="Landslide tramples all players nearby, inflicting Physical damage.", spellID=5568, icon=136063}, {name="Landslide", text="Landslide stuns all players nearby and summons a Theradrim Shardling", spellID=21808, icon=136025}}}
b["lethtendris"] = {description="Dire Maul's warped energy drew Lethtendris from afar, giving her hope of satisfying her unbearable craving for arcane magic. Using the sinews and ligaments of sacrificial victims, she constructed a web to siphon the corrupt power out of the east wing. To her delight, she discovered that the device has the capacity to gather vast reserves of overwhelming strength, enough to destroy all of her enemies.", abilities={{name="Void Bolt", text="Lethtendris inflicts Shadow damage to her target.", spellID=22709, icon=136197}, {name="Shadow Bolt Volley", text="Lethtendris inflicts Shadow damage to all players nearby.", spellID=17228, icon=136197}, {name="Curse of Thorns", text="Lethtendris curses a player with Curse of Thorns. Curse of Thorns has a chance on every melee attack made by the cursed player to inflict...", spellID=16247, icon=136121}, {name="Curse of Tongues", text="Lethtendris curses a player to speak in Demonic. Curse of Tongues reduces casting speed.", spellID=13338, icon=136140}}}
b["lord cobrahn"] = {description="Jarlaxla's skill at harnessing animal forms earned him renown among the druids of the Cenarion Circle. However, the Wailing Caverns' corruption twisted his unique abilities. Now, Jarlaxla has perfected a deadly serpentine form, renaming himself Cobrahn to reflect his vicious newfound power.", abilities={{name="Lightning Bolt", text="Lord Cobrahn hurls a bolt of lightning at his current target, inflicting Nature damage.", icon=136048}, {name="Druid's Slumber", text="Lord Cobrahn puts a player to sleep. Any hostile action will awaken the target.", spellID=8040, icon=136090}, {name="Healing Touch", text="Lord Cobrahn heals an ally.", icon=136041}, {name="Serpent Form", text="Lord Cobrahn transforms into a serpent, increasing his melee damage but increasing the time between his attacks.", spellID=7965, icon=136040}}}
b["lord incendius"] = {description="Baron Geddon taught Incendius to harness his destructive powers, but the baron never expected his protege to grow so lethally efficient. Increasingly wary that Incendius might usurp him, Geddon sent the blazing elemental out of the Molten Core to guard the Dark Iron dwarves' fabled Black Anvil.", abilities={{name="Fire Storm", text="Lord Incendius inflicts Fire damage to all players in a selected area yards in diameter.", spellID=13899, icon=135826}, {name="Fiery Burst", text="Lord Incendius inflicts fire damage to all players in a selected area yards in diameter.", spellID=13900, icon=135809}, {name="Mighty Blow", text="Lord Incendius inflicts Physical damage to a player and knocks them back.", icon=132939}, {name="Curse of the Elemental Lord", text="Lord Incendius reduces the Fire resistance of all players nearby. This effect stacks several charges.", spellID=26977, icon=135819}}}
b["lord pythas"] = {description="A childhood friend of Naralex, the warrior Aryn was a quick study in druidism. Despite his training, the acolyte was defenseless against the corruption that would strip away his sanity. Aryn has taken on the name Pythas, combining his impressive melee prowess with his druidic arsenal to vanquish intruders.", abilities={{name="Lightning Bolt", text="Lord Pythas hurls a bolt of lightning at his current target, inflicting Nature damage.", icon=136048}, {name="Druid's Slumber", text="Lord Pythas puts a player to sleep. Any hostile action will awaken the target.", spellID=8040, icon=136090}, {name="Healing Touch", text="Lord Pythas heals an ally.", icon=136041}, {name="Thunderclap", text="Lord Pythas inflicts Nature damage to all players nearby, increasing the time between their attacks and slowing their movement speed.", spellID=8147, icon=136105}}}
b["lord roccor"] = {description="Lord Roccor loathes the scheming and backstabbing of his fellow fire elementals. To avoid serving alongside his kind in the Molten Core, the mighty being purposefully angered the Firelord. Roccor's risky gambit paid off: he was expelled from the core and forced to guard Blackrock Depths in isolation.", abilities={{name="Ground Tremor", text="Lord Roccor stuns all players nearby.", spellID=6524, icon=136025}, {name="Earth Shock", text="Lord Roccor inflicts Nature damage to a player and interrupts any spell they are casting.", icon=136026}, {name="Flame Shock", text="Lord Roccor inflicts Fire damage to a player. Flame Shock continues to burn that player for Fire damage.", spellID=13729, icon=135813}}}
b["lord serpentis"] = {description="The Druids of the Fang's leader was once Naralex's finest student. His tragic downfall stemmed from his desire to become a shan'do, or \"honored teacher,\" like Naralex. As insanity took root, Serpentis rallied his brethren to his side and formed the Druids of the Fang.", abilities={{name="Lightning Bolt", text="Lord Serpentis hurls a bolt of lightning at his current target, inflicting Nature damage.", icon=136048}, {name="Druid's Slumber", text="Lord Serpentis puts a player to sleep. Any hostile action will awaken the target.", spellID=8040, icon=136090}, {name="Healing Touch", text="Lord Serpentis heals an ally.", icon=136041}}}
b["lord vyletongue"] = {description="The satyr lord Vyletongue journeyed into Maraudon's depths after hearing of its corruption. Theradras was wary of the conniving demon at first, but Vyletongue proved his worth by creating an array of wretched minions, such as Noxxion and Razorlash, for the princess.", abilities={{name="Shoot", text="Lord Vyletongue shoots a random player, inflicting Physical damage.", icon=132222}, {name="Multi-Shot", text="Lord Vyletongue fires a volley of missiles at a random player, inflicting Arcane damage to them and their nearby allies, affecting several...", spellID=21390, icon=132330}, {name="Blink", text="Lord Vyletongue teleports yards forward.", spellID=21655, icon=135736}, {name="Smoke Bomb", text="Lord Vyletongue throws a smoke bomb, stunning all players nearby.", spellID=7964, icon=132156}}}
b["magister kalendris"] = {description="When Prince Tortheldrin demanded the slaughter of the majority of his subjects, his most loyal lieutenants were tasked with executing his will. Magister Kalendris murdered many unsuspecting Shen'dralar without hesitation, but one of the doomed elves mortally wounded him during a destructive battle. Despite his demise, Kalendris's spirit still roams Dire Maul as a defender of Tortheldrin's rule.", abilities={{name="Shadowform", text="Magister Kalendris assumes a form of Shadow at 50% health remaining. Shadowform reduces all damage received and increases Shadow damage...", spellID=22917, icon=136221}, {name="Shadow Word: Pain", text="Magister Kalendris utters a word of darkness, inflicting Shadow damage to an enemy.", spellID=15654, icon=136207}, {name="Mind Flay", text="Magister Kalendris channels dark magic at a player, inflicting Shadow damage and reducing the target's movement speed.", spellID=22919, icon=136208}, {name="Mind Blast", text="Magister Kalendris inflicts Shadow damage to a player.", spellID=452419, icon=136224}}}
b["magistrate barthilas"] = {description="Barthilas was among those innocents purged by Arthas and his forces during the Culling of Stratholme. The Lich King eventually raised the former magistrate from the grave and commanded the hulking undead monstrosity to guard his ruined home.", abilities={{name="Crowd Pummel", text="Magistrate Barthilas pummels all players nearby, inflicting Physical damage, interrupting spellcasting, and knocking them back.", spellID=10887, icon=132938}, {name="Mighty Charge", text="Magistrate Barthilas charges at a random target, inflicting Physical damage and stunning them.", spellID=450961, icon=132939}, {name="Furious Anger", text="Magistrate Barthilas enrages, increasing Physical damage dealt and melee attack speed. This effect stacks.", spellID=16791, icon=136224}, {name="Draining Blows", text="Magistrate Barthilas's critical strikes drain health from his current target, healing himself for the amount drained.", spellID=16793, icon=136130}}}
b["magmus"] = {description="Ambassador Flamelash charged the molten giant Magmus with guarding Emperor Dagran Thaurissan's throne room, but not even this act put the Dark Iron ruler's concerns to rest. Ever fearful of assassins, the emperor also granted Magmus control over a series of fire-breathing statues outside his royal chambers.", abilities={{name="War Stomp", text="Magmus inflicts Physical damage to all players nearby and knocks them away. Players hit by War Stomp are stunned.", spellID=15593, icon=132091}, {name="Fiery Burst", text="Magmus inflicts fire damage to all players within a selected area yards in diameter.", spellID=15668, icon=135809}}}
b["maleki the pallid"] = {description="Maleki was among the first to join the Cult of the Damned, showing tremendous aptitude in harnessing the chill of the grave. Driven by an insatiable desire for power, the mage fervently hones his skills in dark magic to prepare for when he will be remade as a lich.", abilities={{name="Drain Life", text="Maleki the Pallid drains life from his current target, inflicting Shadow damage and healing himself for part of the amount of damage...", spellID=17620, icon=136169}, {name="Frost Armor", text="Maleki the Pallid encases himself in a layer of Frost that reduces his Physical damage taken.", spellID=12556, icon=135843}, {name="Ice Tomb", text="Maleki the Pallid entombs his current target in ice, stunning them.", spellID=16869, icon=135852}, {name="Frostbolt", text="Maleki the Pallid inflicts Frost damage to his current target, reducing their movement speed.", spellID=9672, icon=135846}}}
b["malor the zealous"] = {description="Malor and a handful of other courageous warriors risked everything to protect the Scarlet Bastion from being desecrated by the undead. Tragically, they failed. Balnazzar corrupted the fearless commander into one of his servants, transforming the zealot into a mockery of his former self.", abilities={{name="Ground Smash", text="Commander Malor smashes the ground, inflicting Physical damage to all players nearby and stunning them.", spellID=12734, icon=135906}, {name="Head Crack", text="Commander Malor reduces a player's Stamina.", spellID=16172, icon=132325}, {name="Shadow Bolt Volley", text="Commander Malor hurls missiles of dark magic, inflicting Shadow damage to all players nearby.", spellID=17228, icon=136197}}}
b["mekgineer thermaplugg"] = {description="Murderer, traitor, and self-proclaimed king of the gnomes, the mekgineer Sicco Thermaplugg rules over the radioactive halls of Gnomeregan with a malfunctioning iron fist. His subjects are numerous, vicious, and insane enough to defend their crazed king against any intrusion from the upper world. It is Thermaplugg's madness that makes him so dangerous; he possesses the cunning to destroy everything around him, with no thought for his own life. There is a reason that even the monsters of Gnomeregan fear him.", abilities={{name="Steam Blast", text="Mekgineer Thermaplugg blasts his current target with steam, inflicting Fire damage and knocking them back.", spellID=93655, icon=135831}, {name="Pound", text="Mekgineer Thermaplugg pounds his current target, inflicting Physical damage and disorienting them.", spellID=74720, icon=132154}, {name="Welding Beam", text="Mekgineer Thermplugg blasts his current target with a welding beam, inflicting 250 Nature damage.", spellID=52778, icon=136050}, {name="Detonate", text="Walking Bomb detonates when it reaches its target, inflicting Fire damage to all players nearby.", spellID=11504, icon=135826}}}
b["mordresh fire eye"] = {description="Through necromantic magic Death Speaker Blackthorn was able to rekindle the flames of Mordresh Fire Eye's soul, returning him to undeath. As a former shaman, Mordresh has exerted his twisted control over the elements. He burns and scorches all those who threaten the Death Speaker's work.", abilities={}}
b["morphaz"] = {description="Four promising young drakes accompanied Eranikus into the Temple of Atal'Hakkar, eager to prove themselves by serving a great and powerful wyrm. One by one, they were captured and tainted by the Emerald Nightmare, and they now wander the halls of the Sunken Temple, lashing out at all who intrude upon their waking dream.", abilities={{name="Acid Breath", text="The Wardens of the Dream breath acid, inflicting Nature damage instantly and additional Nature damage to all players in front of them.", spellID=12884, icon=136007}, {name="Wing Flap", text="The Wardens of the Dream thrash their wings, knocking all players in front of them backwards.", icon=136022}}}
b["mother smolderweb"] = {description="Centuries ago, the Dark Iron dwarves dug into the lair of Mother Smolderweb, releasing the massive arachnid into the spire's halls. Her brood has continued to swell in number since that time, so much so that even Blackhand's forces fear traveling through Smolderweb's domain.", abilities={{name="Crystallize", text="Mother Smolderweb stuns all players in front of her.", spellID=16104, icon=136222}, {name="Mother's Milk", text="Mother Smolderweb poisons a random player, causing them and any allies nearby of them to become immobilized periodically.", spellID=16469, icon=132104}, {name="Summon Spire Spiderling", text="Upon death, three Spire Spiderlings are released from Mother Smolderweb's corpse.", icon=134321}}}
b["mr smite"] = {description="As Captain Greenskin's first mate, Smite is tasked with keeping the crew on their toes. Smite is a skilled weaponmaster, trained in all manner of slicing, bashing, and the occasional piercing shot.", abilities={{name="Let's Duel", text="Mr. Smite equips his Thief's Blade, ready to duel the intruders.", icon=135325}, {name="I'll Have to Improvise", text="At 70% health Mr. Smite stomps, stunning all players. He then equips a reaver in each hand, increasing his damage done and granting him...", spellID=6440, icon=132416}, {name="Now I'm Angry", text="At 35% health Mr. Smite stomps, stunning all players, and equips his mighty hammer, increasing his damage done but reducing his attack...", spellID=6436, icon=133046}}}
b["mutanus the devourer"] = {description="From the darkest corners of Naralex's twisted mind, the corruption plaguing the Emerald Dream has manifested in the form of the druid's worst enemy: murlocs. The aberration known as Mutanus has come to the waking world to devour any who seek to liberate Naralex from the Nightmare's clutches.", abilities={{name="Naralex's Nightmare", text="Mutanus the Devourer puts a player to sleep. Any hostile action will awaken the target.", spellID=7967, icon=136090}, {name="Terrify", text="Mutanus the Devourer terrifies a player, causing them to flee in fear.", spellID=7399, icon=132270}, {name="Thundercrack", text="Mutanus the Devourer inflicts Nature damage to all players nearby, stunning them.", spellID=8150, icon=136105}}}
b["nekrum gutchewer"] = {description="Nekrum Gutchewer has mysteriously lived well past his natural life, but his decaying body remains strong enough to aid Sezz'ziz. Together, these two trolls have gathered sacrifices to the mythic beast Gahz'rilla, who slumbers at the city's heart. Many troll followers eagerly await the terrifying creature's awakening, and they will do anything to see the ritual through.", abilities={{name="Fevered Plague", text="Nekrum Gutchewer plagues a player, inflicting Nature damage and more Nature damage over time.", spellID=8600, icon=136066}, {name="Cleave", text="Nekrum Gutchewer inflicts Physical damage on several enemies in front of him.", spellID=40505, icon=132338}}}
b["nerubenkan"] = {description="Nerub'enkan was a fearsome warrior during the War of the Spider. Ultimately, she succumbed to her wounds and was raised into undeath as an obedient minion of the Scourge. Now the nerubian guards a ziggurat in Stratholme as fiercely as she defended her home in life.", abilities={{name="Raise Undead Scarab", text="Nerub'enkan raises scarabs from the dead to aid her in battle.", icon=136132}, {name="Crypt Scarabs", text="Nerub'enkan sends scarabs at several players, inflicting Physical damage.", spellID=31602, icon=136128}, {name="Pierce Armor", text="Nerub'enkan pierces her current target, reducing their armor.", spellID=6016, icon=136231}, {name="Encasing Webs", text="Nerub'enkan encases a player in webs, immobilizing them and increasing the time between their melee attacks.", spellID=4962, icon=136022}}}
b["noxxion"] = {description="Noxxion is a living embodiment of corruption. Theradras ordered her ally Lord Vyletongue to create this putrid elemental to be a powerful servant and a loyal pet to ease the princess's loneliness. Noxxion spreads its toxic essence into areas of Maraudon that have not yet withered under Theradras's malign influence.", abilities={{name="Toxic Volley", text="Noxxion unleashes a volley of toxin, inflicting Nature damage instantly to all players nearby and more Nature damage over time.", spellID=21687, icon=136016}, {name="Uppercut", text="Noxxion uppercuts his current target, inflicting Physical damage and knocking them away.", icon=132939}, {name="Summon Noxxion Spawn", text="Noxxion's body divides into 5 Noxxion Spawn, rendering him unable to fight for up to 20 seconds.", icon=136006}}}
b["obsidian sentinel"] = {description="The Obsidian Sentinel was responsible for guarding Uldaman's secrets until it was corrupted by an unknown force. Originally crafted from the same stone as the halls of Uldaman itself, this keeper has had the majority of its body replaced with dark glass capable of reflecting spells. Whatever was responsible for the Obsidian Sentinel's transformation must be incredibly potent, for it is not easy to alter the enchanted stone of a titan construct.", abilities={{name="Obsidian Reflection", text="Obsidian Sentinel raises a reflective shield, giving it a chance of reflecting the next spell cast at him.", spellID=9941, icon=136222}, {name="Splintered Obisian", text="Obsidian Sentinel splinters, reducing its damage done and summoning an Obsidian Shard.", spellID=10072, icon=136126}, {name="Obsidian Reflection", text="Obsidian Shards raise a reflective shield, giving them a chance of reflecting the next spell cast at them.", spellID=9941, icon=136222}}}
b["olaf"] = {description="Seeking fame, more importantly, fortune, the three brothers Eric, Olaf, and Baelog took on a contract from the Explorers' League to delve deep into the halls of Uldaman and clear a path for a group of researchers. For these three dwarves, however, \"clearing a path\" unfortunately entailed \"getting hopelessly lost in an ancient labyrinth.\" Proud dwarves to the end, they fight to prevent the secrets of Uldaman and the Explorers' League from falling into the hands of the Horde.", abilities={{name="Shield Slam", text="Olaf slams his target, inflicting Physical damage and stunning them.", spellID=8242, icon=132357}}}
b["overlord ramtusk"] = {description="The commander of the Razorfen military forces, Warlord Ramtusk is a massive aging Quilboar whose thick hide bears the scars of many battles with centaur, harpies, orcs, and even tauren. In his later years, Ramtusk has embraced the company of Quilboar spirit leaders; Aggem Thorncurse and Death Speaker Jargba guide his thoughts from the spirit realm.", abilities={}}
b["overlord wyrmthalak"] = {description="The black dragonspawn Wyrmthalak oversees the lower spire's forces as they prepare for their assault against the dwarves. He has no love for the false Horde or its brutish members, and he will sacrifice any number of Blackhand's minions to protect his master, Nefarian.", abilities={{name="Sweeping Slam", text="Overlord Wyrmthalak inflicts Physical damage to all players in front of him, knocking them back.", icon=132111}, {name="Cleave", text="Overlord Wyrmthalak inflicts Physical damage to his current target and their nearest allies, affecting several targets.", spellID=15284, icon=132338}, {name="Demoralizing Shout", text="Overlord Wyrmthalak shouts, reducing melee attack power of all players nearby.", spellID=16244, icon=132366}}}
b["phalanx"] = {description="Until recently, drunken brawls raged within the Grim Guzzler on an almost daily basis. Barkeep Plugger Spazzring has reduced the frequency of these scuffles with Phalanx, a mighty golem bouncer programmed to maintain order in the tavern and eliminate raucous patrons with extreme force.", abilities={{name="Mighty Blow", text="Phalanx inflicts Physical damage to a player and knocks them back.", icon=132939}, {name="Thunderclap", text="Phalanx inflicts Nature damage to all players nearby. Thunderclap slows the melee attack speed of all players it hits and reduces their...", spellID=15588, icon=136105}, {name="Fireball Volley", text="Phalanx inflicts Fire damage to all players nearby.", spellID=15285, icon=135812}}}
b["plugger spazzring"] = {description="They say that at the Grim Guzzler everyone knows your name. This sense of camaraderie is due to the hard work of Spazzring, a leper gnome who sought a new life in Blackrock Depths after the fall of Gnomeregan. Despite his history of dabbling with evil as a warlock, he takes pride in his job as the tavern's barkeep, making sure that his patrons' mugs never run dry.", abilities={{name="Owner of the Grim Guzzler", text="Plugger Spazzring carries the Key to the Grim Guzzler. If players pick Plugger Spazzring's pockets he will alert all of his patrons to..."}, {name="Shadowbolt", text="Plugger Spazzring inflicts Shadow damage to a player.", icon=136197}, {name="Immolate", text="Plugger Spazzring inflicts Fire damage to a player. Immolate continues burning that player for Fire damage.", spellID=12742, icon=135817}, {name="Demon Armor", text="Plugger Spazzring is protected by demonic energies. Demon Armor increases Plugger Spazzring's armor, Shadow resistance, and health...", icon=136185}}}
b["postmaster malown"] = {description="Malown didn't become the Postmaster by not caring about the mail. Even in his current state he is dedicated to maintaining the stability of the postal system. Should that system be disrupted to the point of threatening instability, Malown might just have to take matters into his own hands.", abilities={{name="Fear", text="Postmaster Malown strikes fear in an enemy, causing it to flee in terror. Only 1 target can be feared at a time.", spellID=12542, icon=136183}, {name="Curse of Weakness", text="Postmaster Malown reduces the Physical damage dealt of nearby enemies.", spellID=12741, icon=136138}, {name="Backhand", text="Postmaster Malown backhands an enemy, stunning it.", spellID=6253, icon=132939}, {name="Curse of Tongues", text="Postmaster Malown forces an enemy to speak in Demonic, reducing its casting speed.", spellID=13338, icon=136140}}}
b["prince tortheldrin"] = {description="After the Well of Eternity's destruction, Prince Tortheldrin maintained control over the surviving Shen'dralar by imprisoning a demon in the ruins of Eldre'Thalas and letting his subjects siphon its strength. The exposure to demonic power twisted Tortheldrin's mind, and when the creature faltered, the prince ordered the deaths of many of his vassals so only he and his most fanatical followers would be left to enjoy the corrupt energy.", abilities={{name="Arcane Blast", text="Prince Tortheldrin inflicts Arcane damage to a player and knocks them back.", spellID=22920, icon=136146}, {name="Whirlwind", text="Prince Tortheldrin inflicts Physical damage to all players nearby and knocks them back.", spellID=15589, icon=132369}, {name="Counterspell", text="Prince Tortheldrin interrupts the spellcasting of a player and prevents further spellcasting.", spellID=20537, icon=135856}, {name="Summon", text="When no enemies are in melee range, Prince Tortheldrin summons an enemy to him.", icon=135743}}}
b["princess theradras"] = {description="The earth elemental Theradras, Therazane the Stonemother's sole daughter, resides in Maraudon's inner sanctum. Influenced by the Old Gods, the princess transformed her home into a den of corruption and suffering. Some believe that her foul powers are tied to the spirit of her dead lover, Zaetar. If so, liberating the fallen keeper of the grove might be the only hope of cleansing Maraudon.", abilities={{name="Thrash", text="Princess Theradras thrashes, attacking additional times.", spellID=3391, icon=132152}, {name="Repulsive Gaze", text="Princess Theradras gazes at her current target, fearing all players nearby.", spellID=21869, icon=132154}, {name="Boulder", text="Princess Theradras hurls a boulder at a random player, inflicting Physical damage, interrupting casting and stunning them.", spellID=22592, icon=132324}, {name="Dust Field", text="Princess Theradras shakes the ground, inflicting Nature damage to all players nearby, knocking them back.", spellID=21868, icon=136018}}}
b["pyromancer loregrain"] = {description="Once a respected member of the Earthen Ring, Loregrain joined the Twilight's Hammer cult for reasons that remain a mystery to his former allies. He eventually journeyed to Blackrock Depths, where he took a sudden interest in the famed Dark Iron architect Franclorn Forgewright. The purpose of his current obsession is unclear, but Loregrain remains loyal to his cult and an enemy of all who oppose it.", abilities={{name="Scorch", text="The Scorching Totem inflicts Fire damage to a player.", icon=135825}, {name="Flame Shock", text="Pyromancer Loregrain inflicts Fire damage to a player. Flame Shock continues to inflict Fire damage to that player.", spellID=15616, icon=135813}, {name="Molten Blast", text="Pyromancer Loregrain inflicts Fire damage to a player.", icon=135805}, {name="Fire Ward", text="Pyromancer Loregrain protects himself against Fire damage or until Fire Ward absorbs too much Fire damage.", spellID=15041, icon=135806}}}
b["quartermaster zigris"] = {description="After the First War, the orc hunter Zigris became infamous for tracking down Stormwind refugees and slaughtering them like game. He loathes Blackrock Spire's claustrophobic halls, but he is certain a day will come when he'll hunt in the open air again.", abilities={{name="Hooked Net", text="Quartermast Zigris throws a net, inflicting Physical damage and immobilizing a random player.", spellID=15609, icon=132149}, {name="Drink Healing Potion", text="Quartermast Zigris drinks a healing potion, healing himself.", icon=134834}, {name="Stun Bomb", text="Quartermaster Zigris hurls a bomb at a random player, inflicting Fire damage to all players nearby area and stunning them.", spellID=16497, icon=133716}, {name="Shoot", text="Quartermaster Zigris shoots at his current target when they are not within melee range, inflicting Physical damage.", icon=132222}}}
b["ramstein the gorger"] = {description="Ramstein is one of the Scourge's most infamous abominations, a horror stitched together from numerous corpses and empowered by a ceaseless hunger. This monster committed unspeakable atrocities on countless innocent souls when Scourge forces overran Stratholme.", abilities={{name="Knockout", text="Ramstein the Gorger inflicts Physical damage to his current target, knocking them back, reducing their threat by half, and stunning them.", spellID=17307, icon=132939}, {name="Trample", text="Ramstein the Gorger inflicts Physical damage to all players nearby.", spellID=5568, icon=136063}, {name="Flurry", text="Ramstein the Gorger increases his attack speed for his next attacks after landing a critical strike.", spellID=17687, icon=132152}}}
b["rattlegore"] = {description="Course: Reanimation 101. Rattlegore was thought to have been destroyed in Andorhal, but Gandling immediately began preparations to reanimate the clattering terror so he could guard against intruders. The Darkmaster sought to make Rattlegore more ferocious than ever, imbuing him with an insatiable desire to harvest raw materials from his enemies.", abilities={{name="Rusting", text="Rattlegore's dull blades rust with each successful melee attack, increasing damage but lowering attack speed and movement speed.", spellID=113765, icon=454058}, {name="Bone Spike", text="Rattlegore launches a powerful spike of bone at a random player, inflicting Physical damage and knocking them back a great distance.", spellID=113999, icon=133724}, {name="Soulflame", text="The souls of the dead Boneweavers continue to torment the living, periodically engulfing a section of the room in Soulflame.", spellID=114009, icon=135777}, {name="Bone Armor", text="Surrounds the caster with a series of whirling bones that absorbs one Bone spell.", icon=458236}}}
b["razorlash"] = {description="Razorlash was made to accompany Noxxion through Maraudon. In time, this new creation became one of the princess's most cherished servants. Razorlash constantly wanders the caves alongside Noxxion, using thorny tendrils to shred any untainted plant life it can find.", abilities={{name="Puncture", text="Razorlash punctures its current target, inflicting Physical damage.", spellID=15976, icon=132090}, {name="Thrash", text="Razorlash thrashes its current target, attacking two additional times.", icon=132152}, {name="Cleave", text="Razorlash cleaves, inflicting Physical damage to its current target and their nearest allies, affecting several targets.", spellID=40504, icon=132338}}}
b["revelosh"] = {description="Some luminaries in Ironforge's prestigious Explorers' League have theorized an ancestral link between their people and the troggs, and pointed towards the troggs' hoarding of titan artifacts as a reflection of the dwarves' own reverence for such wondrous devices. If that is true, the trogg known as Revelosh can be considered the trogg equivalent of an archaeologist, although any historically minded adventurers who encounter him would be more inclined to call him a thief.", abilities={{name="Chain Lightning", text="Revelosh strikes his target with a lightning bolt that arcs to nearby players, inflicting Nature damage to targets.", spellID=16006, icon=136015}, {name="Lightning Bolt", text="Revelosh blasts his current target with lightning, inflicting Nature damage.", icon=136048}}}
b["rhahkzor"] = {description="As the Defias Brotherhood's head foreman of the Deadmines, Rhahk'Zor supervises and \"motivates\" the laborers. His methods, though unconventional, are quite effective.", abilities={{name="Rhahk'Zor Slam", text="Rhahk'Zor savagely mauls his current target, inflicting Physical damage and stunning them.", spellID=6304, icon=132939}, {name="Whirlwind", text="Rhahk'Zor enters a spinning rage, attacking nearby enemies in a whirlwind. While he rages, Rhahk'Zor inflicts Physical damage to nearby...", spellID=450515, icon=132369}}}
b["ring of law"] = {description="There is only one punishment for crimes committed against the Dark Iron dwarves: death. Ancient tradition calls for the guilty to pay the blood price in the Ring of the Law by battling savage creatures gathered from across Azeroth. To date, it is unknown if anyone has ever survived this brutal crucible.", abilities={}}
b["roogug"] = {description="Quilboar society regards the reading of stones and crystals as the highest form of shamanism. Roogug served the Quilboar people for many years, quietly honing his divinative arts. He now serves the Quilboar as the overseer of all geomancers and has amassed a powerful array of crystals with which to dispose of weaker foes. It is only a matter of time before these mystics overrun the Southern Barrens.", abilities={}}
b["rotgrip"] = {description="Rumor has it that Rotgrip has dwelled in Maraudon's subterranean waters for millennia. The famed dwarven hunter Hemet Nesingwary once proclaimed that the beast could not be found, and a number of amateur trackers accepted the challenge of seeking out the legendary creature. None of them ever returned.", abilities={{name="Puncture", text="Rotgrip punctures his current target, inflicting Physical damage.", spellID=15976, icon=132090}, {name="Fatal Bite", text="Rotgrip bites his current target, inflicting Physical damage and healing himself for twice the amount of damage dealt.", icon=132090}}}
b["seven"] = {description="Centuries ago, sorcerer-thane Thaurissan and seven of his most powerful Dark Iron allies accidentally summoned Ragnaros into Azeroth and damned their entire clan to enslavement. Although the Seven perished during the ritual, their restless spirits still linger in Blackrock Depths, cursed to serve their elemental master and the current Dark Iron ruler.", abilities={{name="The Seven", text="Doom'rel calls upon the ghosts of his fellow dwarfs to fight players in battle. Each ghost is called in turn, one at a time."}, {name="Prone to Anger", text="Anger'rel enrages when players hit him with a critical melee attack.", icon=136224}, {name="Strike", text="Anger'rel inflicts Physical damage to a player with his weapon.", icon=132282}, {name="Shield Block", text="Anger'rel increases his chance to block incoming attacks.", spellID=12169, icon=132110}}}
b["shade of eranikus"] = {description="Eranikus, former consort to Ysera the Dreamer, was sent to guard the ruins of Atal'Hakkar and prevent Hakkar's emergence. Once within the temple, he and his retinue were corrupted by its dark forces, and he became a shade, pulled between the realms of the Emerald Dream and the physical plane. Despite his corruption, Eranikus may still call upon his powers as a green dragon to spew corrosive acid at his enemies or trap them in a deep slumber.", abilities={{name="Deep Slumber", text="The Shade of Eranikus lulls a player into a deep sleep, stunning them and making them invulnerable.", spellID=12890, icon=136135}, {name="Thrash", text="The Shade of Eranikus thrashes his current target, attacking additional times.", spellID=3391, icon=132152}, {name="War Stomp", text="The Shade of Eranikus stomps, stunning all players nearby.", spellID=11876, icon=132091}, {name="Acid Breath", text="The Shade of Eranikus breaths acid, inflicting Nature damage instantly and additional Nature damage to all players in front of him.", spellID=12891, icon=136007}}}
b["shadow hunter voshgajin"] = {description="Vosh'gajin is renowned for her beauty--and psychotic tendencies--among the trolls. A master of the shadow hunter arts, she wields formidable hexes, curses, and healing magics.", abilities={{name="Hex", text="Shadow Hunter Vosh'gajin transforms a random player into a frog, rendering them unable to attack or cast spells.", spellID=16097, icon=237579}, {name="Curse of Blood", text="Shadow Hunter Vosh'gajin curses all players nearby, increasing their physical damage taken by 90.", spellID=16098, icon=136189}}}
b["shadowpriest sezzziz"] = {description="Nekrum Gutchewer has mysteriously lived well past his natural life, but his decaying body remains strong enough to aid Sezz'ziz. Together, these two trolls have gathered sacrifices to the mythic beast Gahz'rilla, who slumbers at the city's heart. Many troll followers eagerly await the terrifying creature's awakening, and they will do anything to see the ritual through.", abilities={{name="Fevered Plague", text="Nekrum Gutchewer plagues a player, inflicting Nature damage and more Nature damage over time.", spellID=8600, icon=136066}, {name="Cleave", text="Nekrum Gutchewer inflicts Physical damage on several enemies in front of him.", spellID=40505, icon=132338}, {name="Shadow Bolt", text="Shadow Priest Sezz'ziz hurls a bolt of dark magic at a player, inflicting Shadow damage.", spellID=12739, icon=136197}, {name="Psychic Scream", text="Shadow Priest Sezz'ziz lets out a psychic scream, causing all players nearby to flee.", spellID=13704, icon=136184}}}
b["skum"] = {description="Skum first journeyed to the Wailing Caverns for relief from the Barrens' hostile environment. Like many of the caves' other inhabitants, he quickly succumbed to corruption. His veins now pulse with dark energies that have transformed him into a mighty and ruthless beast beyond redemption.", abilities={{name="Chained Bolt", text="Skum strikes a players with a lightning bolt that arcs to other nearby players, inflicting Nature damage. Chain bolt affects several yards.", spellID=6254, icon=136015}}}
b["sneed"] = {description="Sneed was hired as a lumbermaster for his ruthless efficiency. His goal is simple: construct a juggernaut as cheaply as possible. By using the shredder he built himself to lead production, he achieves terrifyingly fast results.", abilities={{name="Disarm", text="Sneed disarms his target, forcing them to stop wielding their weapon.", spellID=6713, icon=132343}}}
b["stomper kreeg"] = {description="On more than one occasion, skulking assassins have met their doom after accidentally disturbing Kreeg's ale mug. Though he's often passed out drunk on duty, nothing rouses the ogre into a berserker fury faster than the sound of his precious drink splattering on the stone floor.", abilities={{name="Booze Spit", text="Stomper Kreeg spits booze at all players in a cone in front of him. Players hit by Booze Spit have their chance to hit reduced and are...", spellID=22833, icon=132792}, {name="War Stomp", text="Stomper Kreeg knocks back all players nearby.", spellID=16740, icon=132091}, {name="Whirlwind", text="Stomper Kreeg inflicts Physical damage to all players nearby.", spellID=15578, icon=132369}, {name="Frenzy", text="Stomper Kreeg attacks faster.", spellID=8269, icon=136224}}}
b["tendris warpwood"] = {description="Tendris Warpwood was a staunch defender of Eldre'Thalas, his heart inexorably entwined with the fate of the city. When the Sundering shattered the land, his resolve never wavered, but as corruption seeped into the ruins over the next 10,000 years, so too did it infect the ancient's spirit.", abilities={{name="Trample", text="Tendris Warpwood inflicts Physical damage to all players nearby.", spellID=5568, icon=136063}, {name="Grasping Vines", text="Tendris Warpwood inflicts Physical damage to all players nearby, knocking them down and immobilizing them.", spellID=22924, icon=136100}, {name="Entangle", text="Tendris Warpwood teleports a player to him and entangles them in roots, inflicting Nature damage and immobilizing them.", spellID=22994, icon=136100}}}
b["theka the martyr"] = {description="Long ago, the martyr Theka was slain in the brutal war between the qiraji and the trolls. Zul'Farrak still stands because of his brave sacrifice. Even in death he maintains a vigil over his beloved city, and it is said that the dozens of insectoid warriors who killed him were cursed to live as mindless scarabs, scuttling at the martyr's side.", abilities={{name="Fevered Plague", text="Theka the Martyr plagues a player, inflicting Nature damage and more Nature damage over time.", spellID=8600, icon=136066}, {name="Shadow Transformation", text="At 30% remaining health Theka the Martyr transforms, increasing his resistance to Physical and Shadow damage.", spellID=11089, icon=136121}, {name="Shadow Bolt Volley", text="Theka hurls missiles of dark magic, inflicting Shadow damage to nearby enemies.", spellID=17228, icon=136197}, {name="Shadow Word: Pain", text="Theka utters a word of darkness, inflicting Shadow damage to an enemy.", spellID=15654, icon=136207}}}
b["timmy the cruel"] = {description="Timmison was infamous for his savagery on the field of battle. Some speculate his sadism stemmed from the ceaseless bullying he endured as a child. Now reborn as a Scourge monstrosity, his mind shattered, he is tormented by those memories, causing him to answer to the name he once loathed: Timmy.", abilities={{name="Thrash", text="Timmy the Cruel thrashes, attacking additional times.", spellID=3391, icon=132152}, {name="Ravenous Claw", text="Timmy the Cruel lashes out, inflicting Physical damage to all enemies in front of him and healing himself for part of damage dealt.", spellID=17470, icon=237535}, {name="Enrage", text="When Timmy the Cruel reaches 50% remaining health, he enrages, increasing his damage dealt and attack speed.", spellID=8599, icon=136224}}}
b["tinkerer gizlock"] = {description="Tinkerer Gizlock and five other gem hunters snuck into Maraudon to mine its highly prized crystals. Their plan went horribly wrong when satyrs slaughtered everyone in the party save for Gizlock. The goblin, trapped within the caves and driven to the brink of madness, sees himself as the subterranean region's new ruler.", abilities={{name="Bomb", text="Tinkerer Gizlock throws a bomb at a random player, inflicting Fire damage to all players nearby.", spellID=9143, icon=135826}, {name="Goblin Dragon Gun", text="Tinkerer Gizlock fires his Goblin Dragon Gun, inflicting 140 Fire damage to all players in front of him.", spellID=21833, icon=135818}, {name="Flash Bomb", text="Tinkerer Gizlock throws a flash bomb, causing all Beasts nearby to flee.", spellID=29419, icon=136142}, {name="Shoot", text="Tinkerer Gizlock shoots a random player, inflicting Physical damage.", icon=132222}}}
b["unforgiven"] = {description="Lylia was a blade of righteousness among her people. After Arthas commanded his forces to purge the city, her sanity was ripped apart from seeing countless innocents die by her hand. She fell on her sword to escape the madness around her, and she now exists as a spectral being forever denied absolution for her heinous acts.", abilities={{name="Unrelenting Anguish", text="The Unforgiven channels a wave of pain and sorrow into the victim, slowing the target and inflicting Shadow damage.", spellID=122832, icon=136214}, {name="Frost Shock", text="Vengeful Phantom shocks player with ice, inflicting Frost damage and reducing their movement speed.", spellID=15089, icon=135849}}}
b["urok doomhowl"] = {description="Doomhowl is the true leader of the spire's ogres. This sinister figure has charmed his trusted aid, Highlord Omokk, with insidious magic to control Doomhowl's minions in his stead. He has gone to great lengths to keep up this charade, ruthlessly killing any ogres who challenge the highlord's rule.", abilities={{name="Intimidating Roar", text="Urok Doomhowl roars, causing all players nearby to flee in fear.", spellID=16508, icon=132154}, {name="Rend", text="Urok Doomhowl rends his current target, inflicting Physical damage", spellID=16509, icon=132155}, {name="Strike", text="Urok Doomhowl strikes his current target, inflicting Physical damage.", icon=132282}}}
b["verdan the everliving"] = {description="Little is known about this creature prior to Naralex's arrival at the Wailing Caverns. Thought to be the caves' original guardian, Verdan the Everliving could not escape the corruption that befell its home. Verdan is allied with the insane druids and maintains its vigil against those who trespass into its domain.", abilities={{name="Grasping Vines", text="Verdan the Everliving grasps all players nearby in vines, inflicting Physical damage, knocking them down and immobilizing them.", spellID=8142, icon=136100}}}
b["viscous fallout"] = {description="The formerly robust and elegantly complex waterways of Gnomeregan are now an irradiated mess filled with toxic slime. A lone water elemental who had dwelt in the gnomes' aquifer became trapped in the contamination, and the pollution corrupted its pure form. It currently wanders the halls of Gnomeregan in anger and agony, a liquid embodiment of the vile poison of Thermaplugg's betrayal.", abilities={{name="Toxic Volley", text="Viscous Fallout unleashes a volley of toxin, inflicting 56 Nature damage to all players nearby and 7 Nature damage.", spellID=21687, icon=136016}}}
b["war master voone"] = {description="During the Second War, Voone led small strike teams on daring missions into the heart of high elven territory. The cunning troll joined the false Horde because he wanted to be its chief strategist, not because he believed in Blackhand's ideology. Voone sees the splinter faction as an underdog, and he enjoys the satisfaction of overcoming insurmountable odds.", abilities={{name="Thrash", text="War Maser Voone thrashes at his current target, attacking additional times.", spellID=3391, icon=132152}, {name="Throw Axe", text="When War Master Voone changes his stance he hurls a massive axe at a random player, inflicting Physical damage and stunning them from.", spellID=16075, icon=132399}, {name="Cleave", text="War Master Voone inflicts Physical damage to his current target and their nearest allies, affecting several targets.", spellID=15284, icon=132338}, {name="Mortal Strike", text="War Master Voone inflicts Physical damage to his current target, reducing the effectiveness of their healing received.", spellID=16856, icon=132355}}}
b["warder stilgiss"] = {description="After years of dedication to Emperor Thaurissan, the cunning mage Stilgiss was entrusted with protecting his clan's coffers in the Black Vault. The loyal dwarf's close friend Houndmaster Grebmar celebrated the occasion by gifting one of his vicious dogs--Verek--to Stilgiss. The mage has put the beast to good use, keeping it at his side to scare off the vault's would-be thieves.", abilities={{name="Frost Nova", text="Warder Stilgiss inflicts Frost damage to players nearby. Players damaged by Frost Nova are immobilized.", spellID=12674, icon=135848}, {name="Frostbolt", text="Warder Stilgiss inflicts Frost damage to a player. Frostbolt slows the movment speed of the player.", spellID=12675, icon=135846}, {name="Frost Armor", text="Warder Stilgiss armors himself in Frost, increasing his armor and causing melee attacks against him to inflict Chilled.", icon=135843}, {name="Frost Ward", text="Warder Stilgiss shields himself against Frost damage or until Frost Ward absorbs too much Frost damage.", spellID=15044, icon=135850}}}
b["weaver"] = {description="Four promising young drakes accompanied Eranikus into the Temple of Atal'Hakkar, eager to prove themselves by serving a great and powerful wyrm. One by one, they were captured and tainted by the Emerald Nightmare, and they now wander the halls of the Sunken Temple, lashing out at all who intrude upon their waking dream.", abilities={{name="Acid Breath", text="The Wardens of the Dream breath acid, inflicting Nature damage instantly and additional Nature damage to all players in front of them.", spellID=12884, icon=136007}, {name="Wing Flap", text="The Wardens of the Dream thrash their wings, knocking all players in front of them backwards.", icon=136022}}}
b["witch doctor zumrah"] = {description="The powerful loa Bwonsamdi watches over the spirits of the Darkspear trolls, but many of the Sandfury tribe's fallen members are offered no such protection after death. These tortured spirits obey Zum'rah, a cruel witch doctor who uses his dark magic to force the city's dead into unending service.", abilities={{name="Awaken Zul'Farrak Zombie", text="Witch Doctor Zum'rah raises a Zul'Farrak Zombie from a nearby grave.", icon=136119}, {name="Ward of Zum'rah", text="Witch Doctor Zum'rah summons a Ward of Zum'rah at his feet. The Ward of Zum'rah summons a Skeleton of Zum'rah", spellID=11086, icon=136232}, {name="Healing Wave", text="Witch Doctor Zum'rah heals an ally.", spellID=15982, icon=136052}, {name="Shadow Bolt", text="Witch Doctor Zum'rah hurls a bolt of dark magic at a player, inflicting Shadow damage.", spellID=12739, icon=136197}}}
b["zevrim thornhoof"] = {description="Desperate to show his worth to the Burning Legion, Zevrim Thornhoof told his masters he could enslave the formidable ancients who still roamed Dire Maul. When his own power proved insufficient, Thornhoof turned to other living creatures for additional energy, butchering them atop his sacrificial altar and harvesting their essence in their final, agonizing moments.", abilities={{name="Intense Pain", text="Zevrim Thornhoof inflicts Shadow damage to all players nearby. This effect stacks.", spellID=22478, icon=136207}, {name="Sacrifice", text="Zevrim Thornhoof teleports a player to his sacrificial altar. Sacrifice stuns the sacrificed player and drains health.", spellID=22651, icon=136120}, {name="Shadow Bolt Volley", text="Zevrim Thornhoof hurls missiles of dark magic, inflicting Shadow damage to nearby enemies nearby.", spellID=17228, icon=136197}}}
-- lower case, apostrophes/quotes/dots dropped, other punctuation a space, a leading "the " dropped
function L.norm(name)
    local s = string.lower(tostring(name or ""))
    s = string.gsub(s, "['\"%.`]", "")
    s = string.gsub(s, "[^%w]+", " ")
    s = string.gsub(s, "^%s+", ""); s = string.gsub(s, "%s+$", "")
    s = string.gsub(s, "^the ", "")
    return s
end

local byName
-- {description=} for the dungeon by area ID, else by its name; nil when the journal has none
function L.dungeon(area, name)
    local d = area and L.dungeons[tonumber(area) or area]
    if d then return d end
    if name == nil then return nil end
    if not byName then
        byName = {}
        for _, row in pairs(L.dungeons) do if row.name then byName[L.norm(row.name)] = row end end
    end
    return byName[L.norm(name)]
end

-- {description=, abilities={{name=, text=, spellID=, icon=}, ...}} or nil
function L.boss(name)
    if type(name) ~= "string" or name == "" then return nil end
    return L.bosses[L.norm(name)]
end
